emmum ima","DROP","farza"],"words":["3","4","2","5"],"correct":["3"]}]$jsonpit$::jsonb WHERE slug = '2b' AND (CASE WHEN pitanja IS NULL THEN TRUE WHEN jsonb_typeof(pitanja) <> 'array' THEN TRUE ELSE jsonb_array_length(pitanja) < 100 END);
UPDATE kvizovi SET pitanja = $jsonpit$[{"type":"checkbox","question":"Koje su temeljne istine vjere (imanski šarti)?","explanation":"Postoji šest imanskih šarta. Znaš li koji nedostaju ovdje?","options":["Vjerovanje u Allaha","Vjerovanje u meleke","Vjerovanje u sreću","Vjerovanje u poslanike","Vjerovanje u prijateljstvo","Vjerovanje u određenje"],"correct":["Vjerovanje u Allaha","Vjerovanje u meleke","Vjerovanje u poslanike","Vjerovanje u određenje"],"answer":"Vjerovanje u Allaha|||Vjerovanje u meleke|||Vjerovanje u poslanike|||Vjerovanje u određenje"},{"type":"checkbox","question":"Koja su es-sifatuz-zatijje (svojstva bića)?","explanation":"Šest svojstava Allahovog bića.","options":["Vudžud","Vahdanijjet","Kidem","Beka","Muhalefetun lil-havadisi","Kijamun bi nefsihi","Hajat","Ilm"],"correct":["Vudžud","Vahdanijjet","Kidem","Beka","Muhalefetun lil-havadisi","Kijamun bi nefsihi"],"answer":"Vudžud|||Vahdanijjet|||Kidem|||Beka|||Muhalefetun lil-havadisi|||Kijamun bi nefsihi"},{"type":"checkbox","question":"Koja su Allahova svojstva savršenstva (es-sifatus-subutijje)?","explanation":"Imamo osam svojstava Allahovog savršenstva. Znaš li koja fale?","options":["Resul","Ilm","Beka","Besar","Iradet","Kidem","Kelam","Tekvin"],"correct":["Ilm","Besar","Iradet","Kelam","Tekvin"],"answer":"Ilm|||Besar|||Iradet|||Kelam|||Tekvin"},{"type":"checkbox","question":"Koji poslanici spadaju u Ulul-Azm?","explanation":"Pet najodabranijih poslanika.","options":["Nuh, a.s.","Ibrahim, a.s.","Musa, a.s.","Isa, a.s.","Muhammed, a.s.","Adem, a.s."],"correct":["Nuh, a.s.","Ibrahim, a.s.","Musa, a.s.","Isa, a.s.","Muhammed, a.s."],"answer":"Nuh, a.s.|||Ibrahim, a.s.|||Musa, a.s.|||Isa, a.s.|||Muhammed, a.s."},{"type":"checkbox","question":"Koje su velike Allahove knjige?","explanation":"Postoje četiri velika kitaba (objave). Koji ovdje fali?","options":["Tevrat","Zebur","Indžil","Kur’an","Suhufi"],"correct":["Tevrat","Indžil","Kur’an"],"answer":"Tevrat|||Indžil|||Kur’an"},{"type":"checkbox","ques