UPDATE kvizovi SET pitanja = $jsonpit$[{"type":"checkbox","question":"Koje navike održavaju našu ličnu higijenu?","explanation":"Čistoća je temelj zdravlja i vjere.","options":["Redovno kupanje","Rezanje nokata","Pranje zuba","Mijenjanje rublja","Spavanje u prljavom"],"answer":"Redovno kupanje|||Rezanje nokata|||Pranje zuba|||Mijenjanje rublja","correct":["Redovno kupanje","Rezanje nokata","Pranje zuba","Mijenjanje rublja"]},{"type":"checkbox","question":"Šta musliman radi prije početka jela?","explanation":"Bonton za stolom počinje čistoćom i Bismillom.","options":["Pere ruke","Kaže Bismilla","Zahvali se kuharu","Priča viceve"],"answer":"Pere ruke|||Kaže Bismilla|||Zahvali se kuharu","correct":["Pere ruke","Kaže Bismilla","Zahvali se kuharu"]},{"type":"checkbox","question":"Koje osobine čine lijep ahlak (karakter)?","explanation":"Lijep karakter krase plemenite osobine.","options":["Iskrenost","Skromnost","Ljubaznost","Oholost","Ogovaranje"],"answer":"Iskrenost|||Skromnost|||Ljubaznost","correct":["Iskrenost","Skromnost","Ljubaznost"]},{"type":"checkbox","question":"Šta namaz razvija u dječijem karakteru?","explanation":"Namaz je škola života i urednosti.","options":["Disciplinu","Tačnost","Čistoću","Lijenost"],"answer":"Disciplinu|||Tačnost|||Čistoću","correct":["Disciplinu","Tačnost","Čistoću"]},{"type":"checkbox","question":"Šta islam strogo zabranjuje (haram)?","explanation":"Haram su djela koja štete ljudima.","options":["Laž","Krađu","Alkohol","Istinu","Pomaganje"],"answer":"Laž|||Krađu|||Alkohol","correct":["Laž","Krađu","Alkohol"]},{"type":"checkbox","question":"Koje su obaveze prema roditeljima?","explanation":"Roditelji zaslužuju našu najveću pažnju.","options":["Poslušnost","Poštovanje","Pomaganje","Vikanje na njih"],"answer":"Poslušnost|||Poštovanje|||Pomaganje","correct":["Poslušnost","Poštovanje","Pomaganje"]},{"type":"checkbox","question":"Šta musliman ne treba raditi tokom jela?","explanation":"Bonton jela zabranjuje ove neuredne navike.","options":["Puhati u hranu","Pričati punim ustima","Birati po tuđem tanjiru","Jesti desnom rukom"],"answer":"Puhati u hranu|||Pričati punim ustima|||Birati po tuđem tanjiru","correct":["Puhati u hranu","Pričati punim ustima","Birati po tuđem tanjiru"]},{"type":"checkbox","question":"Koja mjesta musliman treba održavati čistim?","explanation":"Musliman brine o svojoj okolini.","options":["Tijelo","Odjeću","Sobu","Džamiju","Ulicu"],"answer":"Tijelo|||Odjeću|||Sobu|||Džamiju|||Ulicu","correct":["Tijelo","Odjeću","Sobu","Džamiju","Ulicu"]},{"type":"checkbox","question":"Šta se ubraja u grijehe jezika?","explanation":"Čuvanje jezika čuva naš iman.","options":["Laž","Ogovaranje","Psovka","Salavat"],"answer":"Laž|||Ogovaranje|||Psovka","correct":["Laž","Ogovaranje","Psovka"]},{"type":"checkbox","question":"Šta musliman radi kada završi s jelom?","explanation":"Zahvala i urednost na kraju obroka.","options":["Kaže Elhamdulillah","Pere ruke","Pospremi za sobom","Ostavi sve na stolu"],"answer":"Kaže Elhamdulillah|||Pere ruke|||Pospremi za sobom","correct":["Kaže Elhamdulillah","Pere ruke","Pospremi za sobom"]},{"type":"checkbox","question":"Kako pokazujemo poštovanje prema komšijama?","explanation":"Lijep odnos prema komšiji je dio vjere.","options":["Nazivanjem selama","Pomoći u nevolji","Čuvanjem mira","Bacanjem smeća njima"],"answer":"Nazivanjem selama|||Pomoći u nevolji|||Čuvanjem mira","correct":["Nazivanjem selama","Pomoći u nevolji","Čuvanjem mira"]},{"type":"checkbox","question":"Šta je istina o halalu?","explanation":"Halal put je put sigurnosti.","options":["To je dopušteno","To je zdravo","To je Allah naredio","To je štetno"],"answer":"To je dopušteno|||To je zdravo|||To je Allah naredio","correct":["To je dopušteno","To je zdravo","To je Allah naredio"]},{"type":"checkbox","question":"Koje su odlike skromne osobe?","explanation":"Skromnost je vrlina vjernika.","options":["Ne uzdiže se","Cijeni druge","Tiho priča o sebi","Uvijek se hvali"],"answer":"Ne uzdiže se|||Cijeni druge|||Tiho priča o sebi","correct":["Ne uzdiže se","Cijeni druge","Tiho priča o sebi"]},{"type":"checkbox","question":"Šta kvari prijateljstvo?","explanation":"Ove loše osobine uništavaju povjerenje.","options":["Laž","Ogovaranje","Izdaja tajne","Iskrenost"],"answer":"Laž|||Ogovaranje|||Izdaja tajne","correct":["Laž","Ogovaranje","Izdaja tajne"]},{"type":"checkbox","question":"Šta musliman radi kada vidi smeće na putu?","explanation":"Uklanjanje prepreke s puta je dio imana.","options":["Skloni ga","Ne baca novo","Pravi se da ne vidi"],"answer":"Skloni ga|||Ne baca novo","correct":["Skloni ga","Ne baca novo"]},{"type":"checkbox","question":"Kako se musliman ponaša prema bolesnima?","explanation":"Posjeta bolesniku je velika nagrada.","options":["Posjećuje ih","Donosi im poklon","Moli Allaha za njih","Izbjegava ih"],"answer":"Posjećuje ih|||Donosi im poklon|||Moli Allaha za njih","correct":["Posjećuje ih","Donosi im poklon","Moli Allaha za njih"]},{"type":"checkbox","question":"Šta je odgojni cilj namaza?","explanation":"Namaz oblikuje naš karakter.","options":["Strpljenje","Red","Poniznost","Oholost"],"answer":"Strpljenje|||Red|||Poniznost","correct":["Strpljenje","Red","Poniznost"]},{"type":"checkbox","question":"Koje su koristi srednjeg puta?","explanation":"Umjerenost u svemu je ključ ravnoteže.","options":["Mir u duši","Bolje zdravlje","Umjerenost","Pretjerivanje"],"answer":"Mir u duši|||Bolje zdravlje|||Umjerenost","correct":["Mir u duši","Bolje zdravlje","Umjerenost"]},{"type":"checkbox","question":"Šta ubrajamo u urednost u školi?","explanation":"Vjernik je uredan u svim obavezama.","options":["Čiste sveske","Posložena torba","Bacanje papira","Čuvanje klupe"],"answer":"Čiste sveske|||Posložena torba|||Čuvanje klupe","correct":["Čiste sveske","Posložena torba","Čuvanje klupe"]},{"type":"checkbox","question":"Šta musliman radi kada pogriješi prema nekome?","explanation":"Popravljanje greške je dio tevbe.","options":["Izvine se","Prizna grešku","Traži halal","Krije grešku"],"answer":"Izvine se|||Prizna grešku|||Traži halal","correct":["Izvine se","Prizna grešku","Traži halal"]},{"type":"checkbox","question":"Koja su svojstva iskrenog čovjeka?","explanation":"Iskrenost gradi povjerenje.","options":["Uvijek govori istinu","Ne vara","Drži obećanje","Često laže"],"answer":"Uvijek govori istinu|||Ne vara|||Drži obećanje","correct":["Uvijek govori istinu","Ne vara","Drži obećanje"]},{"type":"checkbox","question":"Kako čuvamo zdravlje tijela?","explanation":"Tijelo je emanet koji moramo čuvati.","options":["Zdravom hranom","Vježbanjem","Dovoljno sna","Pijenjem gaziranog stalno"],"answer":"Zdravom hranom|||Vježbanjem|||Dovoljno sna","correct":["Zdravom hranom","Vježbanjem","Dovoljno sna"]},{"type":"checkbox","question":"Šta musliman radi tokom posjete rodbini?","explanation":"Održavanje rodbinskih veza je važno.","options":["Nazove selam","Lijepo razgovara","Ponudi pomoć","Samo gleda u mobitel"],"answer":"Nazove selam|||Lijepo razgovara|||Ponudi pomoć","correct":["Nazove selam","Lijepo razgovara","Ponudi pomoć"]},{"type":"checkbox","question":"Šta je haram u ishrani?","explanation":"Ove stvari su zabranjene radi zdravlja duše i tijela.","options":["Svinjetina","Alkohol","Meso uginule životinje","Jabuke"],"answer":"Svinjetina|||Alkohol|||Meso uginule životinje","correct":["Svinjetina","Alkohol","Meso uginule životinje"]},{"type":"checkbox","question":"Šta nas uči \"srednji put\"?","explanation":"Sredina je najlakši i najbolji put.","options":["Ne budi škrt","Ne budi rastrošan","Ne jedi previše","Ne spavaj stalno"],"answer":"Ne budi škrt|||Ne budi rastrošan|||Ne jedi previše|||Ne spavaj stalno","correct":["Ne budi škrt","Ne budi rastrošan","Ne jedi previše","Ne spavaj stalno"]},{"type":"reorder","question":"Prilikom jela pratimo određeni bonton. Složi radnje:","explanation":"Red kod jela je dio islamskog bontona.","items":[{"text":"Pranje ruku","order":1},{"text":"Učenje Bismille","order":2},{"text":"Jedenje ispred sebe","order":3},{"text":"Učenje dove nakon jela","order":4}]},{"type":"reorder","question":"Istinoljubivost vodi do velikih nagrada. Poredaj put istine:","explanation":"Istina vodi dobročinstvu.","items":[{"text":"Uvijek govoriti istinu","order":1},{"text":"Sticanje povjerenja kod ljudi","order":2},{"text":"Postizanje Allahovog zadovoljstva","order":3}]},{"type":"reorder","question":"Musliman svoj dan organizuje prema namazima. Složi prioritete:","explanation":"Disciplina počinje namazom.","items":[{"text":"Obavljanje namaza na vrijeme","order":1},{"text":"Učenje i škola","order":2},{"text":"Igra i odmor","order":3}]},{"type":"reorder","question":"Urednost počinje od nas samih. Poredaj radnje čišćenja:","explanation":"Urednost odražava unutrašnju čistoću.","items":[{"text":"Čišćenje tijela (kupanje)","order":1},{"text":"Oblačenje čistog rublja","order":2},{"text":"Oblačenje čiste odjeće","order":3}]},{"type":"reorder","question":"Kako popraviti odnos nakon uvrede? Složi korake:","explanation":"Vjernik brzo ispravlja svoje greške.","items":[{"text":"Priznanje uvrede","order":1},{"text":"Iskreno izvinjenje","order":2},{"text":"Traženje halala","order":3}]},{"type":"reorder","question":"Namaz nas uči disciplini u vaktu. Poredaj namaze:","explanation":"Vremenski okvir namaza nas uči tačnosti.","items":[{"text":"Sabah","order":1},{"text":"Podne","order":2},{"text":"Akšam","order":3}]},{"type":"reorder","question":"Prilikom ulaska u kuću poštujemo red. Složi radnje:","explanation":"Bonton ulaska u kuću.","items":[{"text":"Kucanje na vrata","order":1},{"text":"Nazivanje selama","order":2},{"text":"Izuvanje obuće","order":3}]},{"type":"reorder","question":"Srednji put u trošenju novca znači:","explanation":"Ni škrtost ni rasipništvo.","items":[{"text":"Zadovoljenje osnovnih potreba","order":1},{"text":"Pomaganje drugima","order":2},{"text":"Štednja za budućnost","order":3}]},{"type":"reorder","question":"Priprema za učenje Kur’ana ide ovim redom:","explanation":"Poštovanje prema Allahovoj o