INSERT INTO pitanja_banka (pitanje, opcije, correct_index, correct_indexes, correct_order, objasnjenje, slika, vrsta) VALUES
  ('"Ja sam najvjerodostojnija hadiska zbirka." Koja sam?', '["Sahihul-Buhari","Sahihu-Muslim","Sunen Ebu Davud","Muveta"]'::jsonb, 0, NULL, NULL, 'Sahihul-Buhari - najvjerodostojnija zbirka.', NULL, 'single'),
  ('"Ja sam dan na planini Arefat - suština hadža." Koji sam dan?', '["9. zul-hidže","8. zul-hidže","10. zul-hidže","11. zul-hidže"]'::jsonb, 0, NULL, NULL, '"Hadž je Arefat" - 9. dan.', NULL, 'single'),
  ('Riječ FARDI-KIFAJE asocira na:', '["Dženaza-namaz","Zajednička dužnost","Džemat","Sve navedeno"]'::jsonb, 3, NULL, NULL, 'Fardi-kifaje je zajednička obaveza kao dženaza-namaz.', NULL, 'single'),
  ('Riječ NISAB asocira na:', '["Zekat","Minimalna količina imovine","91.6g zlata","Sve navedeno"]'::jsonb, 3, NULL, NULL, 'Nisab je granica za zekat.', NULL, 'single'),
  ('Riječ FIDJA asocira na:', '["Post","Iskup","Trajno nesposobni","Sve navedeno"]'::jsonb, 3, NULL, NULL, 'Fidja se daje umjesto posta.', NULL, 'single'),
  ('Riječ BEJTUL-MAL asocira na:', '["Zekat","Islamska zajednica","Fond za siromašne","Sve navedeno"]'::jsonb, 3, NULL, NULL, 'Bejtul-mal upravlja zekatom.', NULL, 'single'),
  ('Riječ AREFAT asocira na:', '["Hadž","9. zul-hidže","Najvažniji dan","Sve navedeno"]'::jsonb, 3, NULL, NULL, 'Arefat je srce hadža.', NULL, 'single'),
  ('Riječ IHRAM asocira na:', '["Hadž","Dva bijela platna","Zabranjene radnje","Sve navedeno"]'::jsonb, 3, NULL, NULL, 'Ihram je ritual hadža.', NULL, 'single'),
  ('Riječ SAHIH asocira na:', '["Hadis","Vjerodostojan","Buhari i Muslim","Sve navedeno"]'::jsonb, 3, NULL, NULL, 'Sahih = vjerodostojan hadis.', NULL, 'single'),
  ('Broj 2.5% asocira na:', '["Zekat na novac","Zekat na zlato","Zekat na srebro","Sve navedeno"]'::jsonb, 3, NULL, NULL, '2.5% zekata na novac, zlato, srebro.', NULL, 'single'),
  ('Broj 10% asocira na:', '["Zekat na poljoprivredu","Zalivano kišom","Bez dodatnih troškova","Sve navedeno"]'::jsonb, 3, NULL, NULL, '10% zekata ako je zalivano samo kišom.', NULL, 'single'),
  ('Riječ SADEKATUL-FITR asocira na:', '["Ramazan","Prije bajram-namaza","Čišćenje posta","Sve navedeno"]'::jsonb, 3, NULL, NULL, 'Sadekatul-fitr čisti post.', NULL, 'single'),
  ('Ahmed pita: "Je li dženaza-namaz fard za svakog muslimana?" Odgovor?', '["Da, fardi-ajn","Ne, fardi-kifaje","Ne, sunnet","Da, vadžib"]'::jsonb, 1, NULL, NULL, 'Dženaza-namaz je fardi-kifaje.', NULL, 'single'),
  ('Fatima ima 50g zlata. Mora li dati zekat?', '["Da","Ne, ispod nisaba","Možda","Samo ako hoće"]'::jsonb, 1, NULL, NULL, 'Nisab za zlato je 91.6g.', NULL, 'single'),
  ('Emir ima 100g zlata. Koliko zekata daje?', '["1g","2.5g","5g","10g"]'::jsonb, 1, NULL, NULL, '2.5% od 100g = 2.5g zlata.', NULL, 'single'),
  ('Merjem je teško bolesna i ne može postiti. Šta treba?', '["Fidja","Nadoknaditi kasnije","Kefaret","Ništa"]'::jsonb, 0, NULL, NULL, 'Za trajno nesposobne - fidja.', NULL, 'single'),
  ('Haris planira hadž. Šta mu je PRVO potrebno?', '["Novac","Zdravlje","Mahrem","Ihram"]'::jsonb, 1, NULL, NULL, 'Prvi uvjet: punoljetnost i zdravlje.', NULL, 'single'),
  ('Zejna posti ponedjeljkom. Koji je to post?', '["Farz","Vadžib","Dobrovoljni","Zabranjen"]'::jsonb, 2, NULL, NULL, 'Ponedjeljak je dobrovoljni post.', NULL, 'single'),
  ('Tarik ima usjeve zalivane samo kišom. Koliko zekata?', '["2.5%","5%","7.5%","10%"]'::jsonb, 3, NULL, NULL, 'Samo kiša = 10% zekata.', NULL, 'single'),
  ('Amina daje sadekatul-fitr POSLIJE bajram-namaza. Je li ispravno?', '["Da","Ne, treba prije","Svejedno","Da, ali bolje prije"]'::jsonb, 1, NULL, NULL, 'Sadekatul-fitr se daje PRIJE bajram-namaza.', NULL, 'single'),
