  ('Šta je nisab?', '["Vrsta namaza","Minimalna vrijednost imovine za obavezu zekata","Vrsta posta","Dio hadža"]'::jsonb, 1, NULL, NULL, 'Nisab je minimalna vrijednost imovine koja mora biti u posjedu godinu dana da bi zekat bio obavezan.', NULL, 'single'),
  ('Koji melek će puhanjem u sur najaviti Sudnji dan?', '["Džibril","Mikail","Israfil","Azrail"]'::jsonb, 2, NULL, NULL, 'Israfil će puhanjem u sur najaviti Smak svijeta i Sudnji dan.', NULL, 'single'),
  ('Kako se zove fond u koji se izdvaja zekat u Bosni i Hercegovini?', '["Vakuf","Bejtul-mal","Sadaka","Infak"]'::jsonb, 1, NULL, NULL, 'Zekat se izdvaja u fond Bejtul-mal pri Islamskoj zajednici, odakle se dijeli potrebnim kategorijama.', NULL, 'single'),
  ('Koji dan je najvažniji dan hadža?', '["Dan tavafa","Dan Arefata","Dan Mine","Dan ihrama"]'::jsonb, 1, NULL, NULL, 'Poslanik, a.s., je rekao: ''Hadž je Arefat...'' Deveti dan zul-hidžeta je dan Arefata.', NULL, 'single'),
  ('Koja je prva faza kur''anske zabrane alkohola?', '["Potpuna zabrana","Zabrana pri namazu","Stavljanje u ravan sa štetnim stvarima","Upozorenje na posljedice"]'::jsonb, 2, NULL, NULL, 'Prva faza: alkohol se spominje odvojeno od ''hrane prijatne'', ukazujući da nije dobar (En-Nahl, 67).', NULL, 'single'),
  ('Sura El-Fil je mekanska sura.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Sura El-Fil je mekanska sura i sadrži pet ajeta.', NULL, 'single'),
  ('Sura El-Fil govori o Ebrehi i njegovoj vojsci sa slonovima.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Sura El-Fil govori o Ebrehi koji je pokušao srušiti Kabu s vojskom slonova.', NULL, 'single'),
  ('Ptice ebabil su bacale komade zlata na Ebrehinu vojsku.', '["DA","NE"]'::jsonb, 1, NULL, NULL, 'Ptice ebabil su bacale grumenje od PEČENE GLINE (hidžaretin min sidždžil), ne zlata.', NULL, 'single'),
  ('Sura El-Humeze govori o onima koji gomilaju bogatstvo.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Sura El-Humeze upozorava one koji ogovaraju, klevetaju i gomilaju bogatstvo misleći da će vječno živjeti.', NULL, 'single'),
  ('Et-Tekasur znači ''nadmetanje u imetku''.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Et-Tekasur znači nadmetanje u imetku, mnoštvu, bogatstvu - upozorenje na materijalistički život.', NULL, 'single'),
  ('Sura El-Kari''ah govori o Sudnjem danu.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'El-Kari''ah (Smak svijeta) opisuje strahote Sudnjeg dana kada će ljudi biti poput raštrkanih leptira.', NULL, 'single'),
  ('Dova ''Rabbena atina fid-dunja...'' traži samo dunjalučka dobra.', '["DA","NE"]'::jsonb, 1, NULL, NULL, 'Ova dova traži dobra I na dunjaluku I na ahiretu: ''Gospodaru, daj nam dobro na dunjaluku i dobro na ahiretu.''', NULL, 'single'),
  ('Subhanallah znači ''Hvala Allahu''.', '["DA","NE"]'::jsonb, 1, NULL, NULL, 'Subhanallah znači ''Slavljen neka je Allah''. ''Hvala Allahu'' je Elhamdulillah.', NULL, 'single'),
  ('Bismilla se uči prije svakog posla i jela.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Bismilla (U ime Allaha) se uči prije svakog posla, jela i pića.', NULL, 'single'),
  ('Ajetul-Kursijj je najvredniji ajet u Kur''anu.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Poslanik, a.s., je rekao da je Ajetul-Kursijj (El-Bekare, 255) najvredniji ajet u Kur''anu.', NULL, 'single'),
  ('Sura El-Fatiha ima sedam ajeta.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Sura El-Fatiha (Otvaranje) ima sedam ajeta i naziva se ''es-seb''ul-mesani''.', NULL, 'single'),
  ('Sura El-Kevser je najkraća sura u Kur''anu.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Sura El-Kevser ima samo 3 ajeta i najkraća je sura u Kur''anu.', NULL, 'single'),
  ('Innã lillãhi ve innã ilejhi rãdži''ũn se uči pri radosnim vijestima.', '["DA","NE"]'::jsonb, 1, NULL, NULL, 'Ova dova se uči pri TUŽNIM vijestima i nesrećama: ''Mi smo Allahovi i Njemu se vraćamo.''', NULL, 'single'),
  ('Salavat se uči na Poslanika, a.s.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Salavat (Allãhumme salli, Allãhumme bãrik) se uči na Poslanika Muhammeda, a.s.', NULL, 'single'),
  ('Koliko ajeta ima sura El-Fil?', '["3 ajeta","5 ajeta","7 ajeta","10 ajeta"]'::jsonb, 1, NULL, NULL, 'Sura El-Fil ima 5 ajeta.', NULL, 'single'),
  ('Šta znači ''El-Kari''ah''?', '["Mnoštvo","Slon","Smak svijeta","Ogovaranje"]'::jsonb, 2, NULL, NULL, 'El-Kari''ah znači ''Smak svijeta'' ili ''Lupnjava'' - naziv za Sudnji dan.', NULL, 'single'),
  ('Šta znači ''Elhamdulillah''?', '["Slavljen neka je Allah","Hvala Allahu","Allah je Najveći","U ime Allaha"]'::jsonb, 1, NULL, NULL, 'Elhamdulillah znači ''Hvala Allahu'' ili ''Sva hvala pripada Allahu''.', NULL, 'single'),
  ('Koja dova se uči prije jela?', '["Elhamdulillah","Bismillah","Subhanallah","Allahu Ekber"]'::jsonb, 1, NULL, NULL, 'Prije jela se uči Bismillah (U ime Allaha), a poslije jela Elhamdulillah.', NULL, 'single')
