INSERT INTO pitanja_banka (pitanje, opcije, correct_index, correct_indexes, correct_order, objasnjenje, slika, vrsta) VALUES
  ('Šta ptice ebabil bacaju na Ebrehinu vojsku u suri El-Fil?', '["Vatru","Grumenje od pečene gline","Kamenje","Vodu"]'::jsonb, 1, NULL, NULL, 'Ptice su bacale ''hidžaretin min sidždžil'' - grumenje od pečene gline.', NULL, 'single'),
  ('Koja sura počinje riječima ''Kul huwallahu ehad''?', '["El-Fatiha","El-Ihlas","El-Felek","En-Nas"]'::jsonb, 1, NULL, NULL, 'Sura El-Ihlas počinje: ''Kul huwallahu ehad'' - Reci: On je Allah - Jedan!', NULL, 'single'),
  ('Šta znači ''Allahu Ekber''?', '["Hvala Allahu","U ime Allaha","Allah je Najveći","Slavljen je Allah"]'::jsonb, 2, NULL, NULL, 'Allahu Ekber znači ''Allah je Najveći'' - tekbir koji se uči u namazu i drugim prilikama.', NULL, 'single'),
  ('Koja dova se uči pri izlasku iz kuće?', '["Bismillahi tevekkeltu alallah","Elhamdulillah","Subhanallah","Estagfirullah"]'::jsonb, 0, NULL, NULL, '''Bismillahi tevekkeltu alallah'' - U ime Allaha, oslanjam se na Allaha.', NULL, 'single'),
  ('Šta je Hutama spomenuta u suri El-Humeze?', '["Džennet","Džehennemska vatra","Rijeka","Planina"]'::jsonb, 1, NULL, NULL, 'Hutama je džehennemska vatra koja plamti do srca - kazna za ogovarače i gomilače imetka.', NULL, 'single'),
  ('Koja sura se naziva ''Umm-ul-Kur''an'' (Majka Kur''ana)?', '["El-Ihlas","El-Fatiha","El-Bekare","Jasin"]'::jsonb, 1, NULL, NULL, 'Sura El-Fatiha se naziva Umm-ul-Kur''an (Majka Kur''ana) jer sadrži suštinu cijelog Kur''ana.', NULL, 'single'),
  ('Šta je tevhid?', '["Vjerovanje u meleke","Vjerovanje u Allahovu jednoću","Vjerovanje u knjige","Vjerovanje u Sudnji dan"]'::jsonb, 1, NULL, NULL, 'Tevhid je vjerovanje u Allahovu jednoću - da je samo jedan Bog, Allah, i da Mu niko ravan nije.', NULL, 'single'),
  ('Koji od navedenih namaza NIJE vadžib?', '["Vitr-namaz","Bajram-namaz","Sabah-namaz","Svi navedeni su vadžib"]'::jsonb, 2, NULL, NULL, 'Sabah-namaz je farz, ne vadžib. Vitr i bajram-namazi su vadžib-namazi.', NULL, 'single'),
  ('Koliko rekata sunneta-muekkedea klanjamo dnevno?', '["8 rekata","10 rekata","12 rekata","14 rekata"]'::jsonb, 2, NULL, NULL, '12 rekata pritvrđenih sunneta: 2 sabah, 6 podne (4 prije, 2 poslije), 2 akšam, 2 jacija.', NULL, 'single'),
  ('Šta znači rija'' (mali širk)?', '["Nevjerovanje","Pretvaranje i neiskrenost u djelima","Napuštanje islama","Psovanje Allaha"]'::jsonb, 1, NULL, NULL, 'Rija'' je mali širk - pretvaranje ili neiskrenost, činjenje dobrih djela radi pokazivanja pred ljudima.', NULL, 'single'),
  ('Koja sura govori o propasti vlasnika slona koji su htjeli srušiti Kabu?', '["El-Ihlas","El-Fil","El-Fatiha","El-Kevser"]'::jsonb, 1, NULL, NULL, 'Sura El-Fil govori o Ebrehi i njegovoj vojsci koju je Allah uništio pticama ebabil.', NULL, 'single'),
  ('KO SAM JA? Ja sam melek zadužen za uzimanje duše u času smrti.', '["Džibril","Mikail","Israfil","Azrail"]'::jsonb, 3, NULL, NULL, 'Azrail (Melekul-mevt) je melek smrti koji uzima dušu iz tijela u času smrti.', NULL, 'single'),
  ('DOPUNI: Namaz : loša djela = Post : ___', '["Darežljivost","Bogobojaznost","Moralnost","Znanje"]'::jsonb, 1, NULL, NULL, 'Namaz nas odvraća od lošeg, post nas čini bogobojaznijim, zekat darežljivijim, hadž moralnijim.', NULL, 'single'),
  ('ANALOGIJA: Džibril : objave = Mikail : ___', '["Smrt","Prirodne pojave","Sur","Džennet"]'::jsonb, 1, NULL, NULL, 'Džibril donosi objave, a Mikail je zadužen za prirodne pojave: kišu, vjetar, rast bilja.', NULL, 'single'),
  ('ŠTA JE ZAJEDNIČKO? Kelimei-šehadet, namaz, post, zekat, hadž', '["Imanski šarti","Islamski šarti (farzovi)","Vadžibi","Sunneti"]'::jsonb, 1, NULL, NULL, 'Ovo je pet islamskih šartova - temeljnih dužnosti islama koje su na stepenu farza.', NULL, 'single'),
  ('PRONAĐI GREŠKU: ''Dženaza-namaz ima tri tekbira i klanja se sa rukuom i sedždom.''', '["Ima četiri tekbira","Nema ruku'' i sedždu","Oboje je greška","Nema greške"]'::jsonb, 2, NULL, NULL, 'Dženaza-namaz ima ČETIRI tekbira i NEMA ruku'' ni sedždu - obje tvrdnje su pogrešne.', NULL, 'single'),
  ('KO SAM JA? Ja sam čuvar Dženneta.', '["Malik","Ridvan","Munkir","Nekir"]'::jsonb, 1, NULL, NULL, 'Ridvan je melek čuvar Dženneta, a Malik je čuvar Džehennema.', NULL, 'single'),
  ('IZBACI ULJEZA: Koji od navedenih NIJE melek?', '["Munkir","Nekir","Iblis","Ridvan"]'::jsonb, 2, NULL, NULL, 'Iblis (šejtan) nije melek, on je džin koji je odbio učiniti sedždu Ademu, a.s.', NULL, 'single'),
  ('DOPUNI NIZ: Sabah, podne, ikindija, ___', '["Džuma","Akšam","Vitr","Teravih"]'::jsonb, 1, NULL, NULL, 'Pet dnevnih namaza redom: sabah, podne, ikindija, AKŠAM, jacija.', NULL, 'single'),
  ('ANALOGIJA: Kufr : nevjerovanje = Nifak : ___', '["Širk","Licemjerstvo","Zulum","Haram"]'::jsonb, 1, NULL, NULL, 'Kufr je nevjerovanje, a nifak je licemjerstvo - skrivanje nevjerovanja u srcu.', NULL, 'single'),
  ('ŠTA JE ZAJEDNIČKO? Vitr-namaz, ramazanski bajram-namaz, kurbanski bajram-namaz', '["Farz-namazi","Vadžib-namazi","Sunnet-namazi","Nafile"]'::jsonb, 1, NULL, NULL, 'Svi navedeni su vadžib-namazi - propisani ali nisu na stepenu farza.', NULL, 'single'),
  ('KO SAM JA? Mi smo meleki koji prate ljude i zapisuju njihova djela.', '["Munkir i Nekir","Kiramen-katibin","Harut i Marut","Zebanije"]'::jsonb, 1, NULL, NULL, 'Kiramen-katibin (časni pisari) prate ljude, pišu njihova djela i donose im dobre misli.', NULL, 'single'),
  ('PRONAĐI GREŠKU: ''Sadekatul-fitr se daje samo za odrasle članove porodice.''', '["Daje se i za maloljetne","Daje se samo za muškarce","Nema greške","Daje se samo za žene"]'::jsonb, 0, NULL, NULL, 'Sadekatul-fitr se daje za svakog muslimana - i punoljetnog i maloljetnog.', NULL, 'single'),
  ('DOPUNI: Er-Rahman : Milostivi = El-Gaffar : ___', '["Pravedni","Onaj Koji mnogo prašta","Stvoritelj","Sveznajući"]'::jsonb, 1, NULL, NULL, 'Er-Rahman znači Milostivi, a El-Gaffar znači Onaj Koji mnogo prašta.', NULL, 'single'),
  ('IZBACI ULJEZA: Koji pojam NE pripada istoj kategoriji?', '["Kufr","Širk","Nifak","Ihsan"]'::jsonb, 3, NULL, NULL, 'Kufr, širk i nifak su grijesi/negativni pojmovi, a ihsan je savršenstvo u vjeri - pozitivan pojam.', NULL, 'single'),
  ('KO SAM JA? Mi smo meleki koji ispituju svakog čovjeka u kaburu.', '["Kiramen-katibin","Munkir i Nekir","Harut i Marut","Zebanije"]'::jsonb, 1, NULL, NULL, 'Munkir i Nekir su meleki koji ispituju svakog čovjeka u mezaru (kaburu).', NULL, 'single'),
  ('ANALOGIJA: Veliki širk : obožavanje drugog = Mali širk : ___', '["Nevjerovanje","Pretvaranje (rija'')","Napuštanje islama","Psovanje"]'::jsonb, 1, NULL, NULL, 'Veliki širk je obožavanje nekoga pored Allaha, a mali širk (rija'') je pretvaranje u djelima.', NULL, 'single'),
  ('ŠTA JE ZAJEDNIČKO? 2 sabah, 6 podne, 2 akšam, 2 jacija', '["Farz-namazi","Vadžib-namazi","Sunneti-muekkedea","Sunneti gajri-muekkedea"]'::jsonb, 2, NULL, NULL, 'Ovo su sunneti-muekkedea (pritvrđeni sunneti) koje je Poslanik, a.s., uvijek klanjao.', NULL, 'single'),
  ('PRONAĐI GREŠKU: ''Zekat se daje od 10% na svu imovinu.''', '["Zekat je 2.5%, ne 10%","Ne daje se na svu imovinu","Oboje je greška","Nema greške"]'::jsonb, 1, NULL, NULL, 'Zekat je 2.5% (ne 10%) i daje se samo na imovinu koja dostiže nisab - oboje je pogrešno.', NULL, 'single'),
  ('DOPUNI NIZ: Džibril, Mikail, Israfil, ___', '["Ridvan","Azrail","Malik","Munkir"]'::jsonb, 1, NULL, NULL, 'Četiri najpoznatija meleka: Džibril, Mikail, Israfil i Azrail.', NULL, 'single'),
  ('KO SAM JA? Ja sam abesinski vladar koji je pokušao srušiti Kabu sa vojskom slonova.', '["Faraon","Ebreha","Nemrud","Karun"]'::jsonb, 1, NULL, NULL, 'Ebreha je abesinski vladar čija je vojska uništena pticama ebabil kada je krenuo srušiti Kabu.', NULL, 'single'),
  ('IZBACI ULJEZA: Koja od navedenih stvari NE kvari ihrame?', '["Šišanje","Namaz","Mirisanje","Lov"]'::jsonb, 1, NULL, NULL, 'Namaz ne kvari ihrame. Zabrane za muhrime su: šišanje, mirisanje, lov, spolni odnos...', NULL, 'single'),
  ('ANALOGIJA: Džennet : Ridvan = Džehennem : ___', '["Azrail","Israfil","Malik","Munkir"]'::jsonb, 2, NULL, NULL, 'Ridvan je čuvar Dženneta, a Malik je čuvar Džehennema.', NULL, 'single'),
  ('ŠTA JE ZAJEDNIČKO? Vudžud, Vahdanijet, Kidem, Beka', '["Allahova imena","Allahova svojstva (sifati)","Vrste namaza","Dijelovi hadža"]'::jsonb, 1, NULL, NULL, 'Ovo su Allahova svojstva (sifati): Postojanje, Jednoća, Vječnost, Trajnost.', NULL, 'single'),
  ('PRONAĐI GREŠKU: ''Bajram-namaz se klanja u tri rekata.''', '["Klanja se u dva rekata","Klanja se u četiri rekata","Nema greške","Klanja se u jedan rekat"]'::jsonb, 0, NULL, NULL, 'Bajram-namaz (i ramazanski i kurbanski) ima DVA rekata, ne tri.', NULL, 'single'),
  ('SITUACIJA: Hasan je zaboravio proučiti Fatihu u jednom rekatu. Šta treba učiniti?', '["Namaz je ispravan","Treba učiniti sehvi-sedždu","Mora ponoviti cijeli namaz","Treba ponoviti samo taj rekat"]'::jsonb, 2, NULL, NULL, 'Učenje Fatihe je farz namaza. Ako se izostavi, namaz nije ispravan i mora se ponoviti.', NULL, 'single'),
  ('DOPUNI: Subhaneke : prvi tekbir = Salavati : ___', '["Drugi tekbir","Treći tekbir","Četvrti tekbir","Ruku''"]'::jsonb, 0, NULL, NULL, 'U dženaza-namazu: nakon prvog tekbira uči se Subhaneke, nakon drugog salavati.', NULL, 'single'),
  ('KO SAM JA? Ja sam Allahovo svojstvo koje znači da je On Sveznajući.', '["El-Halik","El-Alim","El-Aziz","El-Kerim"]'::jsonb, 1, NULL, NULL, 'El-Alim znači Sveznajući - Allah zna ono što ne znaju Njegova stvorenja.', NULL, 'single'),
  ('IZBACI ULJEZA: Koji pojam NE pripada kategoriji uvjeta za hadž?', '["Punoljetnost","Materijalne mogućnosti","Brak","Sigurnost puta"]'::jsonb, 2, NULL, NULL, 'Brak nije uvjet za hadž. Uvjeti su: punoljetnost, zdravlje, materijalne mogućnosti, sigurnost puta.', NULL, 'single'),
  ('ANALOGIJA: Namaz : Kijam = Dženaza-namaz : ___', '["Stajanje u safovima","Ruku''","Sedžda","Sjedenje"]'::jsonb, 0, NULL, NULL, 'U redovnom namazu kijam je stajanje, a u dženaza-namazu se stoji u safovima (farz).', NULL, 'single'),
  ('ŠTA JE ZAJEDNIČKO? Tehijetul-mesdžid, hadže-namaz, istihara-namaz', '["Farz-namazi","Vadžib-namazi","Sunneti gajri-muekkedea (nafile)","Sunneti-muekkedea"]'::jsonb, 2, NULL, NULL, 'Ovo su sunneti gajri-muekkedea (nepritvrđeni sunneti/nafile) koje je Poslanik povremeno klanjao.', NULL, 'single'),
  ('PRONAĐI GREŠKU: ''Telbija se uči nakon skidanja ihrama.''', '["Uči se nakon oblačenja ihrama","Uči se samo na Arefatu","Nema greške","Uči se samo žene"]'::jsonb, 0, NULL, NULL, 'Telbija se uči NAKON OBLAČENJA ihrama i nastavlja se učiti tokom hadža.', NULL, 'single'),
  ('SITUACIJA: Fatima nije postila jedan dan ramazana zbog menstruacije. Šta treba učiniti?', '["Dati fidju","Napostiti taj dan nakon ramazana","Ništa, automatski je oprošteno","Klanjati kaza-namaz"]'::jsonb, 1, NULL, NULL, 'Žena koja ne posti zbog menstruacije mora napostiti propuštene dane nakon ramazana.', NULL, 'single'),
  ('DOPUNI NIZ: Es-sifatuz-zatijje, es-sifatus-subutijje, ___', '["Es-sifatul-fi''lijje","El-esmaul-husna","El-esmaul-dželal","Es-sifatul-kamilijje"]'::jsonb, 1, NULL, NULL, 'Allahova svojstva i imena: es-sifatuz-zatijje (svojstva bića), es-sifatus-subutijje (svojstva savršenstva), el-esmaul-husna (lijepa imena).', NULL, 'single'),
  ('KO SAM JA? Ja sam vrsta namaza koja se klanja kada vjernik ima neku potrebu i traži uputu od Allaha.', '["Hadže-namaz","Istihara-namaz","Tehijetul-mesdžid","Duha-namaz"]'::jsonb, 1, NULL, NULL, 'Istihara-namaz se klanja kada vjernik traži uputu od Allaha u donošenju neke odluke.', NULL, 'single'),
  ('IZBACI ULJEZA: Šta NE spada u zabrane za muhrime (osobe u ihramima)?', '["Lov","Učenje Kur''ana","Šišanje","Mirisanje"]'::jsonb, 1, NULL, NULL, 'Učenje Kur''ana nije zabranjeno muhrimima. Zabrane su: lov, šišanje, mirisanje, spolni odnos...', NULL, 'single'),
  ('ANALOGIJA: Islamski šarti : 5 = Imanski šarti : ___', '["4","5","6","7"]'::jsonb, 2, NULL, NULL, 'Islamskih šartova ima 5 (šehadet, namaz, post, zekat, hadž), a imanskih šartova ima 6.', NULL, 'single'),
  ('ŠTA JE ZAJEDNIČKO? Arefat, Mina, Muzdelifa', '["Dijelovi namaza","Mjesta na hadžu","Vrste posta","Allahova imena"]'::jsonb, 1, NULL, NULL, 'Arefat, Mina i Muzdelifa su sveta mjesta koja se posjećuju tokom obavljanja hadža.', NULL, 'single'),
  ('PRONAĐI GREŠKU: ''Džuma-namaz je obavezan svim muslimanima, uključujući i žene.''', '["Nije obavezan ženama","Nije obavezan nikome","Nema greške","Obavezan je samo imamu"]'::jsonb, 0, NULL, NULL, 'Džuma-namaz je obavezan punoljetnim, zdravim muslimanima MUŠKARCIMA. Ženama nije farz.', NULL, 'single'),
  ('DOPUNI: Innã lillãhi ve innã ilejhi rãdži''ũn : saučešće = Innallãhe me''as-sãbirĩn : ___', '["Odgovor na saučešće","Dova za umrlog","Selam","Zahvala"]'::jsonb, 0, NULL, NULL, '''Svi smo Allahovi i Njemu se vraćamo'' je saučešće, a ''Allah je sa strpljivima'' je odgovor na saučešće.', NULL, 'single'),
  ('KO SAM JA? Ja sam Allahovo ime koje znači Stvoritelj.', '["El-Melik","El-Halik","El-Kuddus","Es-Selam"]'::jsonb, 1, NULL, NULL, 'El-Halik znači Tvorac/Stvoritelj - Allah koji je stvorio kosmos i sve što postoji.', NULL, 'single'),
  ('IZBACI ULJEZA: Šta NE spada u mudrost propisivanja zekata?', '["Čisti dušu od škrtosti","Čisti i povećava imetak","Zamjenjuje namaz","Sprečava nagomilavanje imetka"]'::jsonb, 2, NULL, NULL, 'Zekat ne zamjenjuje namaz - to su dvije odvojene dužnosti. Zekat čisti dušu, imetak i uspostavlja dobro.', NULL, 'single'),
  ('ANALOGIJA: Farz : stroga obaveza = Vadžib : ___', '["Zabrana","Obaveza koja nije strogo naređena kao farz","Preporuka","Pokušaj"]'::jsonb, 1, NULL, NULL, 'Farz je stroga obaveza, vadžib je obaveza koja nije strogo naređena kao farz.', NULL, 'single'),
  ('ŠTA JE ZAJEDNIČKO? La ilahe illallah, Allahu Ekber, Subhanallah', '["Dove","Zikrovi (spominjanje Allaha)","Dijelovi namaza","Sure"]'::jsonb, 1, NULL, NULL, 'Ovo su zikrovi - različiti načini spominjanja i veličanja Allaha, dž.š.', NULL, 'single'),
  ('PRONAĐI GREŠKU: ''Münzir i Nekir su meleki čuvari Dženneta i Džehennema.''', '["Oni ispituju u kaburu","To su Ridvan i Malik","Oboje je greška","Nema greške"]'::jsonb, 2, NULL, NULL, 'Munkir i Nekir ISPITUJU u kaburu. Čuvari Dženneta i Džehennema su RIDVAN i MALIK.', NULL, 'single'),
  ('DOPUNI NIZ: Tekbir, kiraet (Fatiha i sura), ruku'', ___', '["Selam","Sedžda","Ka''de","Ettehijjatu"]'::jsonb, 1, NULL, NULL, 'Redoslijed u namazu: tekbir, kiraet, ruku'', SEDŽDA, pa zatim drugi rekat...', NULL, 'single'),
  ('KO SAM JA? Ja sam Allahovo svojstvo koje znači da On nema ni početka ni kraja.', '["Vudžud","Vahdanijet","Kidem i Beka","Kudret"]'::jsonb, 2, NULL, NULL, 'Kidem (Vječnost - nema početka) i Beka (Trajnost - nema kraja) zajedno znače da Allah nema ni početka ni kraja.', NULL, 'single'),
  ('IZBACI ULJEZA: Šta NE pripada dijelovima hadža?', '["Tavaf","Sa''j","I''tikaf","Vakfa na Arefatu"]'::jsonb, 2, NULL, NULL, 'I''tikaf je boravak u džamiji (obično u ramazanu), nije dio hadža. Tavaf, sa''j i vakfa jesu dijelovi hadža.', NULL, 'single'),
  ('ANALOGIJA: Sur : Israfil = Vahj (objava) : ___', '["Mikail","Azrail","Džibril","Malik"]'::jsonb, 2, NULL, NULL, 'Israfil će puhnuti u sur, a Džibril je donosio vahj (objavu) poslanicima.', NULL, 'single'),
  ('ŠTA JE ZAJEDNIČKO? Safa, Merva, Hadžerul-esved, Kaba', '["Dijelovi namaza","Sveta mjesta u Mekki","Allahova svojstva","Vrste posta"]'::jsonb, 1, NULL, NULL, 'Safa, Merva, Hadžerul-esved i Kaba su sveta mjesta u Mekki vezana za hadž.', NULL, 'single'),
  ('PRONAĐI GREŠKU: ''Sunneti-muekkedea su namazi koje je Poslanik, a.s., povremeno izostavljao.''', '["Nikada ih nije izostavljao","To su sunneti gajri-muekkedea","Oboje je greška","Nema greške"]'::jsonb, 0, NULL, NULL, 'Sunneti-muekkedea (pritvrđeni sunneti) su namazi koje Poslanik, a.s., NIKADA nije izostavljao.', NULL, 'single'),
  ('DOPUNI: Fatiha : farz = Sura poslije Fatihe : ___', '["Farz","Vadžib","Sunnet","Mekruh"]'::jsonb, 1, NULL, NULL, 'Učenje Fatihe je farz namaza, a učenje sure poslije Fatihe je vadžib.', NULL, 'single'),
  ('KO SAM JA? Ja sam dova koja se uči za umrlog nakon trećeg tekbira u dženaza-namazu.', '["Subhaneke","Salavati","Dženaza-dova","Kunut-dova"]'::jsonb, 2, NULL, NULL, 'Redoslijed u dženaza-namazu: 1. tekbir - Subhaneke, 2. tekbir - salavati, 3. tekbir - dženaza-dova, 4. tekbir - selam.', NULL, 'single'),
  ('IZBACI ULJEZA: Koji pojam NE pripada osobinama munafika?', '["Laže kada govori","Ne ispunjava obećanja","Čuva emanet","Prelazi granice u svađi"]'::jsonb, 2, NULL, NULL, 'Osobine munafika: laže, ne ispunjava obećanja, iznevjerava povjereno i prelazi granice. ''Čuva emanet'' je suprotno - pozitivna osobina.', NULL, 'single'),
  ('ANALOGIJA: Ramazan : post = Zul-hidždže : ___', '["Post","Hadž","Zekat","Namaz"]'::jsonb, 1, NULL, NULL, 'Ramazan je mjesec posta, a Zul-hidždže je mjesec hadža.', NULL, 'single'),
  ('ŠTA JE ZAJEDNIČKO? Kupanje (gusul), ćefini, stavljanje ispred džemata, okretanje prema Kibli', '["Uvjeti za namaz","Uvjeti za ispravnost dženaza-namaza","Dijelovi hadža","Uvjeti za post"]'::jsonb, 1, NULL, NULL, 'Ovo su uvjeti za ispravnost dženaza-namaza: da je umrli musliman, okupan, u ćefinima, ispred džemata i okrenut prema Kibli.', NULL, 'single'),
  ('PRONAĐI GREŠKU: ''Zekat se daje osam kategorija osoba spomenutih u suri El-Bekare.''', '["Spomenute su u suri Et-Tevbe","Ima ih sedam kategorija","Ima ih devet kategorija","Nema greške"]'::jsonb, 0, NULL, NULL, 'Kategorije kojima se daje zekat spomenute su u 60. ajetu sure ET-TEVBE, ne El-Bekare.', NULL, 'single'),
  ('DOPUNI NIZ: Esmaul-džemal, esmaul-dželal, ___', '["Esmaul-kemal","Esmaul-husna","Esmaul-azim","Esmaul-ilahi"]'::jsonb, 0, NULL, NULL, 'Podjela Allahovih imena: esmaul-džemal (ljepote), esmaul-dželal (uzvišenosti), esmaul-kemal (savršenstva).', NULL, 'single'),
  ('KO SAM JA? Ja sam mjesto između Arefata i Mine gdje hadžije klanjaju akšam i jaciju.', '["Mina","Safa","Muzdelifa","Merva"]'::jsonb, 2, NULL, NULL, 'Muzdelifa je mjesto između Arefata i Mine gdje hadžije klanjaju akšam i jaciju spojeno.', NULL, 'single'),
  ('IZBACI ULJEZA: Šta NE spada u es-sifatuz-zatijje (svojstva Allahovog bića)?', '["Vudžud (Postojanje)","Kudret (Moć)","Kidem (Vječnost)","Vahdanijet (Jednoća)"]'::jsonb, 1, NULL, NULL, 'Kudret (Moć) spada u es-sifatus-subutijje (svojstva savršenstva), ne u es-sifatuz-zatijje (svojstva bića).', NULL, 'single'),
  ('ANALOGIJA: Haram : zabranjeno = Mekruh : ___', '["Dozvoljeno","Pokuđeno","Naređeno","Obavezno"]'::jsonb, 1, NULL, NULL, 'Haram je zabranjeno, a mekruh je pokuđeno (nije zabranjeno, ali se ne preporučuje).', NULL, 'single'),
  ('ŠTA JE ZAJEDNIČKO? 4 ikindija sunneta, 4 jacijska sunneta, tehijetul-mesdžid', '["Sunneti-muekkedea","Sunneti gajri-muekkedea","Farzovi","Vadžibi"]'::jsonb, 1, NULL, NULL, 'Ovo su sunneti gajri-muekkedea (nepritvrđeni sunneti) koje je Poslanik, a.s., povremeno izostavljao.', NULL, 'single'),
  ('PRONAĐI GREŠKU: ''U vitr-namazu se uči Kunut-dova prije ruku''a u trećem rekatu.''', '["Uči se poslije ruku''a","Uči se u drugom rekatu","Nema greške","Ne uči se Kunut-dova"]'::jsonb, 0, NULL, NULL, 'Kunut-dova se uči POSLIJE ruku''a u trećem rekatu vitr-namaza, ne prije.', NULL, 'single'),
  ('SITUACIJA: Porodica Smajlović želi dati sadekatul-fitr za 5 članova. Kome trebaju dati?', '["Direktno siromahu","U Bejtul-mal","Džamiji","Sve navedeno je ispravno"]'::jsonb, 1, NULL, NULL, 'U BiH, sadekatul-fitr se daje u Bejtul-mal pri Islamskoj zajednici, odakle se distribuira potrebnima.', NULL, 'single'),
  ('Sura El-Kafirun je objavljena u Mekki.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tačno! Sura El-Kafirun je mekanska sura i ima 6 ajeta.', NULL, 'single'),
  ('Sura El-Kevser ima 3 ajeta.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tačno! El-Kevser je najkraća sura u Kur''anu sa samo 3 ajeta.', NULL, 'single'),
  ('Sura El-Maun ima 7 ajeta.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tačno! Sura El-Maun je objavljena u Mekki i ima 7 ajeta.', NULL, 'single'),
  ('Sura El-Kurejš ima 6 ajeta.', '["DA","NE"]'::jsonb, 1, NULL, NULL, 'Netačno! Sura El-Kurejš ima 4 ajeta, ne 6.', NULL, 'single'),
  ('Kunut-dova se uči u vitr-namazu.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tačno! Kunut-dova se uči u trećem rekatu vitr-namaza.', NULL, 'single'),
  ('Riječ "Kevser" znači "mnogo dobro".', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tačno! El-Kevser znači "mnogo dobro" ili "obilje" koje je Allah dao Poslaniku.', NULL, 'single'),
  ('El-Kafirun govori o prijedlogu idolopoklonika Poslaniku.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tačno! Idolopoklonici su predložili da Poslanik obožava kipove jednu godinu, a oni Allaha drugu.', NULL, 'single'),
  ('"Lekum dinukum ve lije din" znači "Vama vaša vjera, a meni moja".', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tačno! To je posljednji ajet sure El-Kafirun.', NULL, 'single'),
  ('Sura El-Maun govori o onima koji grubo odbijaju siroče.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tačno! El-Maun kritizira one koji odbijaju jetima i ne pomažu siromašnima.', NULL, 'single'),
  ('El-Kurejš govori o stanovnicima Medine.', '["DA","NE"]'::jsonb, 1, NULL, NULL, 'Netačno! El-Kurejš govori o stanovnicima MEKKE - Kurejšijama.', NULL, 'single'),
  ('Bismilla se uči na početku svake sure.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tačno! Bismillahir-rahmanir-rahim se uči na početku svake sure.', NULL, 'single'),
  ('Poslanik je bio nasmijan nakon objave sure El-Kevser.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tačno! Enes ibn Malik prenosi da je Poslanik nakratko zadrijemao pa se nasmiješen probudio.', NULL, 'single'),
  ('Riječ "ebter" znači "onaj koji će bez spomena ostati".', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tačno! Nevjernici su Poslanika prozvali "ebter", ali Allah kaže da će oni ostati bez spomena.', NULL, 'single'),
  ('Dova poslije jela počinje sa "El-hamdu lillahi".', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tačno! El-hamdu lillahillezi at''amena ve sekana ve dže''alena minel-muslimin.', NULL, 'single'),
  ('Kunut-dova se uči u prvom rekatu vitr-namaza.', '["DA","NE"]'::jsonb, 1, NULL, NULL, 'Netačno! Kunut-dova se uči u TREĆEM rekatu vitr-namaza.', NULL, 'single'),
  ('U suri El-Maun Allah kritizira munafike koji klanjaju radi ljudi.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tačno! Drugi dio sure govori o munaficima koji klanjaju da ih ljudi vide.', NULL, 'single'),
  ('"Innã e''tajnãkel-kevser" je prvi ajet sure El-Kevser.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tačno! Znači: "Mi smo ti, uistinu, mnogo dobro dali."', NULL, 'single'),
  ('Estagfirullah je dova za traženje oprosta.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tačno! Estagfirullah znači: "Tražim Allahov oprost."', NULL, 'single'),
  ('Sura El-Kurejš spominje zimsko i ljetno putovanje Kurejšija.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tačno! "Navike njihove da zimi i ljeti putuju" - trgovačka putovanja.', NULL, 'single'),
  ('Fatiha se uči na svakom rekatu namaza.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tačno! Fatiha je obavezna na svakom rekatu namaza.', NULL, 'single'),
