  ('Koliko ajeta ima sura El-Kevser?', '["3","4","5","6"]'::jsonb, 0, NULL, NULL, 'Sura El-Kevser ima samo 3 ajeta - najkraća sura.', NULL, 'single'),
  ('Koliko ajeta ima sura El-Maun?', '["5","6","7","8"]'::jsonb, 2, NULL, NULL, 'Sura El-Maun ima 7 ajeta.', NULL, 'single'),
  ('Koliko ajeta ima sura El-Kurejš?', '["3","4","5","6"]'::jsonb, 1, NULL, NULL, 'Sura El-Kurejš ima 4 ajeta.', NULL, 'single'),
  ('Gdje je objavljena sura El-Kafirun?', '["U Mekki","U Medini","U Taifu","U Jemenu"]'::jsonb, 0, NULL, NULL, 'El-Kafirun je MEKANSKA sura.', NULL, 'single'),
  ('Koja sura počinje sa "Kul ja ejjuhel-kafirun"?', '["El-Ihlas","El-Kafirun","El-Kevser","El-Maun"]'::jsonb, 1, NULL, NULL, '"Reci: O vi nevjernici" - početak sure El-Kafirun.', NULL, 'single'),
  ('Šta znači riječ "Kevser"?', '["Nevjernici","Mnogo dobro","Siroče","Kurejšije"]'::jsonb, 1, NULL, NULL, 'KEVSER znači "mnogo dobro" ili "obilje".', NULL, 'single'),
  ('Šta znači riječ "Kafirun"?', '["Vjernici","Nevjernici","Siromasi","Putnici"]'::jsonb, 1, NULL, NULL, 'KAFIRUN znači nevjernici.', NULL, 'single'),
  ('Šta znači riječ "Maun"?', '["Nevjernici","Siroče","Pomoć/zekat","Kurejšije"]'::jsonb, 2, NULL, NULL, 'MA''UN znači "pomoć" ili "ono što se daje drugima".', NULL, 'single'),
  ('Ko su Kurejšije?', '["Stanovnici Medine","Stanovnici Mekke","Stanovnici Taifa","Stanovnici Jemena"]'::jsonb, 1, NULL, NULL, 'KUREJŠIJE su pleme koje je živjelo u Mekki.', NULL, 'single'),
  ('Kada se uči Kunut-dova?', '["Na prvom rekatu","Na drugom rekatu","Na trećem rekatu vitira","Poslije namaza"]'::jsonb, 2, NULL, NULL, 'Kunut-dova se uči u TREĆEM rekatu vitr-namaza.', NULL, 'single'),
  ('Koji namaz ima Kunut-dovu?', '["Sabah","Podne","Vitr","Džuma"]'::jsonb, 2, NULL, NULL, 'VITR-namaz ima Kunut-dovu u trećem rekatu.', NULL, 'single'),
  ('"Fesalli li rabbike venhar" znači:', '["Reci nevjernicima","Moli se i kurban kolji","Vama vaša vjera","Koji gladne hrani"]'::jsonb, 1, NULL, NULL, '"Zato se Gospodaru svome moli i kurban kolji" - El-Kevser.', NULL, 'single'),
  ('Sura El-Maun kritizira one koji:', '["Klanjaju redovno","Grubo odbijaju siroče","Pomažu siromašne","Daju zekat"]'::jsonb, 1, NULL, NULL, 'El-Maun kritizira one koji grubo odbijaju jetima.', NULL, 'single'),
  ('Šta je "jetim" u suri El-Maun?', '["Bogataš","Siroče","Putnik","Nevjernik"]'::jsonb, 1, NULL, NULL, 'JETIM je siroče - dijete bez roditelja.', NULL, 'single'),
  ('Koji ajet je posljednji u suri El-Kafirun?', '["La e''abudu ma ta''budun","Lekum dinukum ve lije din","Inne šani''eke huvel-ebter","Kul ja ejjuhel-kafirun"]'::jsonb, 1, NULL, NULL, '"Vama vaša vjera, a meni moja" - posljednji ajet.', NULL, 'single'),
  ('"Ellezi at''amehum min džu''in" znači:', '["Koji ih gladne hrani","Vama vaša vjera","Koji grubo odbija","Mnogo dobro dali"]'::jsonb, 0, NULL, NULL, '"Koji ih gladne hrani" - iz sure El-Kurejš.', NULL, 'single'),
  ('Dova "Allahumme inna neste''inuke" je dio:', '["Namaska dova","Kunut-dova","Dova poslije jela","Dova za iftar"]'::jsonb, 1, NULL, NULL, 'To je početak KUNUT-DOVE.', NULL, 'single'),
  ('Koja sura govori o putovanjima Kurejšija?', '["El-Kafirun","El-Kevser","El-Maun","El-Kurejš"]'::jsonb, 3, NULL, NULL, 'El-KUREJŠ govori o zimskim i ljetnim putovanjima.', NULL, 'single'),
  ('"Ve amenehum min havf" znači:', '["Koji gladne hrani","Od straha brani","Vama vaša vjera","Mnogo dobro"]'::jsonb, 1, NULL, NULL, '"I od straha brani" - iz sure El-Kurejš.', NULL, 'single'),
  ('Sura El-Kevser je objavljena zbog:', '["Idolopoklonika","Onih koji su Poslanika prozvali ebter","Kurejšija","Siročadi"]'::jsonb, 1, NULL, NULL, 'Objavljena jer su nevjernici rekli da će Poslanik ostati bez spomena.', NULL, 'single'),
  ('Namaska dova počinje sa:', '["Bismillah","Subhaneke","Euzubillah","El-hamdu lillah"]'::jsonb, 2, NULL, NULL, 'Namaska dova počinje sa E''UZU BILLAHI MINEŠ-ŠEJTANIR-RADŽIM.', NULL, 'single'),
  ('"Fevejlun lil-musallin" znači:', '["Hvala Allahu","Teško onima koji klanjaju","Vama vaša vjera","Mnogo dobro"]'::jsonb, 1, NULL, NULL, '"A teško onima koji, kad molitvu obavljaju..." - El-Maun.', NULL, 'single'),
  ('Šta El-Maun kritizira kod nekih klanjača?', '["Da klanjaju previše","Da klanjaju radi ljudi","Da klanjaju noću","Da klanjaju sami"]'::jsonb, 1, NULL, NULL, 'Kritizira munafike koji klanjaju radi toga da ih ljudi vide.', NULL, 'single'),
  ('Dova poslije jela završava sa:', '["Amin","Minel-muslimin","Subhanallah","Elhamdulillah"]'::jsonb, 1, NULL, NULL, '...ve dže''alena MINEL-MUSLIMIN (i učinio nas muslimanima).', NULL, 'single'),
  ('Koja sura je najkraća u Kur''anu?', '["El-Kafirun","El-Kevser","El-Maun","El-Ihlas"]'::jsonb, 1, NULL, NULL, 'EL-KEVSER sa 3 ajeta je najkraća sura.', NULL, 'single'),
  ('"Rabbena atina fid-dunja haseneten" je dio:', '["Kunut-dove","Namaska dove","Dove poslije jela","Fatihe"]'::jsonb, 1, NULL, NULL, '"Gospodaru naš, daj nam dobro na dunjaluku..." - namaska dova.', NULL, 'single'),
  ('Kunut-dova se uči poslije:', '["Fatihe","Sure","Tekbira","Fatihe i sure"]'::jsonb, 3, NULL, NULL, 'U trećem rekatu vitira, poslije Fatihe i sure, donese se tekbir pa Kunut.', NULL, 'single'),
  ('Hram spomenut u suri El-Kurejš je:', '["Medžid","Kaba","Aksa","Hira"]'::jsonb, 1, NULL, NULL, '"Neka se oni Gospodaru ovoga HRAMA klanjaju" - Kaba.', NULL, 'single'),
  ('Izbaci suru koja NE pripada: El-Kafirun, El-Kevser, El-Fatiha, El-Maun', '["El-Kafirun","El-Kevser","El-Fatiha","El-Maun"]'::jsonb, 2, NULL, NULL, 'El-Kafirun, El-Kevser i El-Maun su sure iz 2. nivoa, El-Fatiha je iz 1. nivoa.', NULL, 'single'),
  ('Izbaci pojam koji NE pripada: Kunut-dova, Namaska dova, Fatiha, Dova poslije jela', '["Kunut-dova","Namaska dova","Fatiha","Dova poslije jela"]'::jsonb, 2, NULL, NULL, 'Kunut-dova, Namaska dova i Dova poslije jela su DOVE, Fatiha je SURA.', NULL, 'single'),
  ('Izbaci pojam koji NE pripada: Kafirun, Kurejš, Kevser, Vitr', '["Kafirun","Kurejš","Kevser","Vitr"]'::jsonb, 3, NULL, NULL, 'Kafirun, Kurejš i Kevser su SURE, Vitr je NAMAZ.', NULL, 'single'),
  ('Izbaci broj koji NE pripada (broj ajeta): 3, 4, 6, 10', '["3","4","6","10"]'::jsonb, 3, NULL, NULL, '3 (Kevser), 4 (Kurejš), 6 (Kafirun) su brojevi ajeta, 10 nije.', NULL, 'single'),
  ('Izbaci riječ koja NE pripada: Jetim, Miskin, Kafir, Džemat', '["Jetim","Miskin","Kafir","Džemat"]'::jsonb, 3, NULL, NULL, 'Jetim (siroče), Miskin (siromah), Kafir (nevjernik) se spominju u surama; Džemat nije.', NULL, 'single'),
  ('Izbaci pojam koji NE pripada: Mekka, Medina, Kurejš, Kevser', '["Mekka","Medina","Kurejš","Kevser"]'::jsonb, 1, NULL, NULL, 'Mekka, Kurejš i Kevser su povezani sa mekanskim surama; Medina nije.', NULL, 'single'),
