  ('Dopuni: Kufr : nevjerovanje = Nifak : ?', '["Iskrenost","Licemjerstvo","Hrabrost","Skromnost"]'::jsonb, 1, NULL, NULL, 'Kufr je nevjerovanje, Nifak je licemjerstvo.', NULL, 'single'),
  ('Dopuni: Iskrenost : vrlina = Laž : ?', '["Vrlina","Grijeh","Pohvala","Nagrada"]'::jsonb, 1, NULL, NULL, 'Iskrenost je vrlina, Laž je grijeh.', NULL, 'single'),
  ('Dopuni: Mali grijeh : upozorenje = Teški grijeh : ?', '["Nagrada","Izlazak iz vjere","Pohvala","Blagoslov"]'::jsonb, 1, NULL, NULL, 'Mali grijeh nosi upozorenje, Teški grijeh izvodi iz vjere.', NULL, 'single'),
  ('"Ja sam pokajanje za učinjeni grijeh." Šta sam?', '["Namaz","Tevba","Post","Sadaka"]'::jsonb, 1, NULL, NULL, 'TEVBA je pokajanje za učinjene grijehe.', NULL, 'single'),
  ('"Ja sam teški grijeh - nevjerovanje u Allaha." Šta sam?', '["Širk","Kufr","Nifak","Riddet"]'::jsonb, 1, NULL, NULL, 'KUFR je nevjerovanje u Allaha i temeljne istine vjere.', NULL, 'single'),
  ('"Ja sam vrlina - govorim istinu i držim obećanja." Šta sam?', '["Oholost","Laž","Iskrenost","Prevara"]'::jsonb, 2, NULL, NULL, 'ISKRENOST znači govoriti istinu i držati obećanja.', NULL, 'single'),
  ('"Ja sam dijete bez roditelja." Ko sam?', '["Musafir","Jetim","Muallim","Imam"]'::jsonb, 1, NULL, NULL, 'JETIM je siroče - dijete bez roditelja.', NULL, 'single'),
  ('"Ja sam licemjerstvo - javno vjerujem, tajno poričem." Šta sam?', '["Kufr","Širk","Nifak","Riddet"]'::jsonb, 2, NULL, NULL, 'NIFAK je licemjerstvo u vjeri.', NULL, 'single'),
