  ('Šta kvari post?', '["namjerno jelo i piće","pušenje","povraćanje punim ustima","zaboravljanje da se posti"]'::jsonb, 0, '[0,1,2]'::jsonb, NULL, 'Zaborav ne kvari post.', NULL, 'multiple'),
  ('Šta karakteriše namaz u džematu?', '["predvodi ga imam","vrijedi 27 puta više","safovi moraju biti ravni","obavlja se samo petkom"]'::jsonb, 0, '[0,1,2]'::jsonb, NULL, 'Džemat se može formirati za bilo koji namaz.', NULL, 'multiple'),
  ('Označi radnje koje kvare abdest:', '["prirodna nužda","oticanje krvi ili gnoja","povraćanje punim ustima","dubok san","jedenje hrane","smijeh"]'::jsonb, 0, '[0,1,2,3]'::jsonb, NULL, 'Jedenje hrane ne kvari abdest.', NULL, 'multiple'),
  ('Šta karakteriše podne-namaz?', '["ima 4 rekata sunneta","ima 4 rekata farza","klanja se samo u džematu","ukupno 10 rekata","uči se naglas","najduži namaz"]'::jsonb, 3, NULL, NULL, 'Podne-namaz se uči u sebi.', NULL, 'single'),
  ('Koja su vremena kada je pokuđeno klanjati?', '["pri izlasku sunca","utorkom","kada je sunce u zenitu","pri zalasku sunca","iza jacije"]'::jsonb, 0, '[0,2,3]'::jsonb, NULL, 'Postoje tri zabranjena vremena.', NULL, 'multiple'),
  ('Koji su uvjeti za ispravan post?', '["biti musliman","prekinuti post hurmom (datulom)","biti pri pameti","jesti samo BIO hranu","biti punoljetan","biti zdrav i sposoban"]'::jsonb, 0, '[0,2,4,5]'::jsonb, NULL, 'To su obavezni uvjeti za post.', NULL, 'multiple'),
  ('Šta se uči na zadnjem sjedenju namaza?', '["Et-Tehijjatu","Salavati","Fatiha","Dove","Subhaneke"]'::jsonb, 0, '[0,1,3]'::jsonb, NULL, 'Subhaneke i Fatiha se uče na stajanju.', NULL, 'multiple'),
  ('Koje imovine podliježu obavezi zekata?', '["novac","zlato i srebro","trgovačka roba","stoka","osnovni namještaj","privatno auto"]'::jsonb, 0, '[0,1,2,3]'::jsonb, NULL, 'Na auto, kuću i namještaj se ne daje zekat.', NULL, 'multiple'),
  ('Kada putnik (musafir) skraćuje namaz?', '["put od minimalno 80 km","kad god želi","napuštanje mjesta boravka","boravak kraći od 15 dana","svako putovanje van grada"]'::jsonb, 0, '[0,2,3]'::jsonb, NULL, 'To su uvjeti za status musafira.', NULL, 'multiple'),
  ('Šta karakteriše akšam-namaz?', '["klanja se poslije zalaska sunca","ima 3 rekata farza","ima 2 rekata sunneta","ima ukupno 4 rekata"]'::jsonb, 0, '[0,1,2]'::jsonb, NULL, 'Akšam ima ukupno 5 rekata.', NULL, 'multiple'),
  ('Šta karakteriše vitr-namaz?', '["ima 3 rekata","klanja se nakon jacije","uči se Kunut-dova","klanja se u džematu","spada u stroge farzove"]'::jsonb, 0, '[0,1,2]'::jsonb, NULL, 'Vitr je obavezan (vadžib) namaz, a u ramazanu se klanja u džematu.', NULL, 'multiple'),
