  ('Šta se smatra grijehom neposlušnosti?', '["vrijeđanje roditelja","psovanje svetinja","laganje","namjerno ostavljanje namaza"]'::jsonb, 0, '[0,1,2,3]'::jsonb, NULL, 'Ovo su teški prijestupi.', NULL, 'multiple'),
  ('Koja je važnost namaza u islamu?', '["stub je vjere","drugi šart islama","prvo pitanje na Sudnjem danu","jedina obaveza muslimana"]'::jsonb, 0, '[0,1,2]'::jsonb, NULL, 'Namaz je najvažniji ibadet tijelom.', NULL, 'multiple'),
  ('Šta spada u uvjete za namaz (šarte)?', '["čistoća","propisna odjeća","vrijeme","kibla","nijet","ezan","učenje sure"]'::jsonb, 0, '[0,1,2,3,4]'::jsonb, NULL, 'Ezan i učenje sure nisu uvjeti za namaz.', NULL, 'multiple'),
  ('Koji su farzovi gusula?', '["isprati usta","isprati nos","oprati cijelo tijelo","koristiti šampon","oprati ruke"]'::jsonb, 0, '[0,1,2]'::jsonb, NULL, 'Gusul ima tri farza.', NULL, 'multiple'),
