INSERT INTO pitanja_banka (pitanje, opcije, correct_index, correct_indexes, correct_order, objasnjenje, slika, vrsta) VALUES
  ('Kako se rješava tuđi emanet (dug)?', '["Dogovor o roku vraćanja","Čuvanje stvari/novca kao svog","Vraćanje duga na dogovoreni dan","Zahvala osobi na povjerenju"]'::jsonb, 0, NULL, '[1,2,3,4]'::jsonb, 'Dugovi su ozbiljna stvar u islamu.', NULL, 'reorder'),
  ('Postupanje u javnom prevozu:', '["Ulazak bez guranja","Pomeranje unutra da drugima ne smetaš","Ustupanje mjesta trudnici ili starcu"]'::jsonb, 0, NULL, '[1,2,3]'::jsonb, 'Kultura u saobraćaju je dio opšte kulture muslimana.', NULL, 'reorder'),
  ('Slijed pri kupovini u prodavnici:', '["Pozdravljanje prodavača","Strpljivo čekanje u redu","Iskreno plaćanje i uzimanje računa","Ljubazan pozdrav na odlasku"]'::jsonb, 0, NULL, '[1,2,3,4]'::jsonb, 'Musliman je pošten i ljubazan kupac.', NULL, 'reorder'),
  ('Kako se postaje "vođa" u dobru?', '["Lični primjer (radiš dobro)","Pozivanje drugih da se pridruže","Strpljenje dok se rezultati ne vide"]'::jsonb, 0, NULL, '[1,2,3]'::jsonb, 'Djela govore više od riječi.', NULL, 'reorder'),
  ('Pravilno korištenje interneta:', '["Provjera nijjeta (zašto sam online)","Gledanje korisnih sadržaja","Izbjegavanje ružnih komentara i rasprava","Gašenje uređaja na vrijeme"]'::jsonb, 0, NULL, '[1,2,3,4]'::jsonb, 'Ahlak važi i u digitalnom svijetu.', NULL, 'reorder'),
  ('Briga o vlastitoj sobi:', '["Prozračivanje prostorije","Sklanjanje odjeće u ormar","Brisanje prašine i usisavanje"]'::jsonb, 0, NULL, '[1,2,3]'::jsonb, 'Čistoća mjesta gdje boravimo utiče na našu dušu.', NULL, 'reorder'),
  ('Redoslijed pri davanju savjeta:', '["Savjetovanje nasamo (da niko ne čuje)","Korištenje blagih i biranih riječi","Nada da će osoba prihvatiti savjet"]'::jsonb, 0, NULL, '[1,2,3]'::jsonb, 'Javno savjetovanje je zapravo sramoćenje osobe.', NULL, 'reorder'),
  ('Kako su stanovnici Medine dočekali Muhammeda ﷺ nakon hidžre?', '["Sumnjičavo i hladno","S velikom radošću i ljubavlju","Neprimjetno","Samo kao trgovca"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Koji je prvi veliki korak Poslanik ﷺ poduzeo u Medini da bi zajednica dobila duhovni i društveni centar?', '["Napravio palaču","Izgradio džamiju","Podigao tvrđavu","Otvorio tržnicu"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Zašto je džamija u Medini bila više od obične zgrade?', '["Jer je služila samo za odmor putnika","Bila je mjesto ibadeta, znanja, savjetovanja i zajedništva","Bila je kraljevski dvor","Služila je samo kao škola za djecu"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Šta je Poslanik ﷺ učinio između muhadžira i ensarija da bi uklonio osjećaj stranosti i učvrstio zajednicu?', '["Razdvojio ih po bogatstvu","Pobratiomio ih u vjeri","Dao prednost samo starijima","Zabranio im trgovinu"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Zašto je to bratimljenje bilo toliko važno u medinskom periodu?', '["Da bi se ljudi samo formalno upoznali","Da bi se zajednica gradila na pomoći, saosjećanju i zajedničkoj odgovornosti","Da bi se svi preselili u istu kuću","Da bi nastala nova vojska"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Kako je Poslanik ﷺ upravljao zajednicom u Medini?', '["Samo silom","Pravedno, savjetovanjem i milošću","Potpunim povlačenjem","Prepuštajući sve drugima"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Kako se Poslanik ﷺ odnosio prema siromašnima, slabima i potrebitima u Medini?', '["Prepuštao ih je drugima","Učio je zajednicu da ih pomaže i štiti","Smatrao ih je teretom","Pomagao je samo bogatima"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Zašto je medinski period važan za razumijevanje islama?', '["Jer tu vidimo kako vjera postaje življena zajednica, a ne samo pojedinačna riječ","Jer tu nema nikakvih pouka","Jer je tada sve bilo lahko","Jer je Poslanik ﷺ prestao podučavati ljude"]'::jsonb, 0, NULL, NULL, '', NULL, 'single'),
  ('Kako je Poslanik ﷺ postupao kada su zajednicu pogađale teškoće, prijetnje i sukobi?', '["Gubio je nadu","Ostajao je saburan, mudar i oslonjen na Allaha","Odustajao je od vođenja zajednice","Uvijek je birao najlakši put bez principa"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Koja osobina Poslanika ﷺ posebno dolazi do izražaja u medinskom periodu?', '["Samo hrabrost u boju","Sposobnost da spoji pravdu, blagost i vođenje zajednice","Ljubav prema raskoši","Želja da se osami"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Šta nam govori način na koji je Poslanik ﷺ odgajao ljude u Medini?', '["Da se zajednica gradi samo naredbama","Da se srca odgajaju primjerom, znanjem i strpljenjem","Da djeca nisu važna u zajednici","Da je dovoljno imati samo zakon bez odgoja"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Zašto je osvajanje Mekke poseban vrhunac medinskog perioda?', '["Zato što je to bio trenutak potpune osvete","Zato što se tada jasno pokazala snaga oprosta i milosti","Zato što je tada Poslanik ﷺ napustio islam","Zato što je to bio samo vojni događaj bez pouke"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Kako je Poslanik ﷺ postupio prema ljudima Mekke kada je ušao kao pobjednik?', '["Kaznio ih bez izuzetka","Oprostio im je i dao im sigurnost","Protjerao je sve iz grada","Uzeo im je svu imovinu"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Zašto je taj oprost bio toliko velik čin?', '["Jer je oprostio ljudima koji su ga godinama progonili, vrijeđali i ratovali protiv njega","Jer je oprostio samo onima koji su ga hvalili","Jer nije znao šta da uradi","Jer nije imao drugog izbora"]'::jsonb, 0, NULL, NULL, '', NULL, 'single'),
  ('Šta završni medinski period pokazuje o prirodi Poslanika ﷺ?', '["Da je bio vođa bez osjećaja","Da je bio milost i u trenutku kada je mogao uzvratiti","Da je volio pokazivati moć","Da je zaboravio prošlost"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Kako je Poslanik ﷺ svojim životom u Medini pokazivao šta znači vođstvo?', '["Vođa mora biti najbogatiji","Vođa služi ljudima, usmjerava ih dobru i nosi odgovornost","Vođa ne mora slušati nikoga","Vođa se drži samo daleko od običnog naroda"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Šta djeca mogu posebno naučiti iz medinskog perioda?', '["Da je dovoljno samo govoriti o dobru","Da zajednica raste kada ljudi dijele, praštaju i pomažu jedni drugima","Da su važni samo veliki događaji","Da je ibadet odvojen od života"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Koja je jedna od najvećih poruka povratka u Mekku?', '["Pobjeda vrijedi samo ako poniziš druge","Najveća pobjeda je kada ostaneš milostiv i pravedan","Treba se uvijek sjećati samo nepravde","Najjači je onaj ko se osveti"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Kako medinski period zaokružuje životnu misiju Muhammeda ﷺ?', '["Pokazuje kako je od male skupine vjernika nastala uređena zajednica zasnovana na vjeri i pravdi","Pokazuje da je poslanstvo završilo bez promjene ljudi","Pokazuje da je islam ostao samo privatna stvar","Pokazuje da je najvažnija politika bez karaktera"]'::jsonb, 0, NULL, NULL, '', NULL, 'single'),
  ('Koja je glavna pouka medinskog perioda?', '["Vjera se živi kroz zajedništvo, pravdu, milost i odgovornost","Dovoljno je imati samo snagu","Najvažnije je širiti strah","Zajednica je manje važna od pojedinca"]'::jsonb, 0, NULL, NULL, '', NULL, 'single'),
  ('U kojem gradu je rođen Muhammed ﷺ, grad u kojem se nalazila Kaba i u koji su dolazile arapske karavane?', '["Medina","Taif","Mekka","Jerusalem"]'::jsonb, 2, NULL, NULL, '', NULL, 'single'),
  ('Šta je posebno tužno u vezi s rođenjem Muhammeda ﷺ, što njegovom djetinjstvu daje ton iskušenja još od prvog dana?', '["Rodio se u siromašnoj kući","Rodio se bez oca, jer je Abdullah preselio prije njegovog rođenja","Odmah je morao napustiti Mekku","Bio je bolestan pri rođenju"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Kako se zvala majka Muhammeda ﷺ, čestita žena koja ga je nosila i rodila kao siroče?', '["Hatidža","Amina","Halima","Fatima"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Ko je preuzeo brigu o Muhammedu ﷺ nakon smrti njegove majke, pokazujući mu toplinu i zaštitu u ranom djetinjstvu?', '["Ebu Talib","Abdulmuttalib","Hamza","Abbas"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Ko je nakon smrti djeda nastavio brinuti o Muhammedu ﷺ i štitio ga godinama, iako sam nije bio bogat čovjek?', '["Ebu Bekr","Bilal","Ebu Talib","Osman"]'::jsonb, 2, NULL, NULL, '', NULL, 'single'),
  ('Koji nadimak su Mekkelije dale Muhammedu ﷺ još prije poslanstva, jer nikada nisu od njega doživjele laž, izdaju ni prevaru?', '["El-Faruk","El-Emin","El-Mustafa","Es-Sadik"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Šta zapravo znači nadimak El-Emin, koji su mu ljudi dali zbog njegovog karaktera?', '["Onaj koji mnogo govori","Pobjednik","Pouzdani i povjerljivi","Onaj koji putuje"]'::jsonb, 2, NULL, NULL, '', NULL, 'single'),
  ('Zašto je nadimak El-Emin bio toliko važan u Meki, gradu trgovine, ugovora i povjerenih stvari?', '["Jer je bio najbogatiji mladić","Jer su ljudi njemu povjeravali svoje stvari, znajući da ih neće iznevjeriti","Jer je bio pjesnik","Jer je vodio karavane od djetinjstva"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Čime se Muhammed ﷺ bavio u mladosti, kao i mnogi poslanici prije njega, učeći strpljenju, smirenosti i odgovornosti?', '["Bavio se samo trgovinom","Čuvao je stoku","Bio je vojnik","Pisao je knjige"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Zašto je važno što je Muhammed ﷺ odrastao kao siroče?', '["Da bi postao slabiji od drugih","Da bi kasnije mogao razumjeti bol, usamljenost i potrebu slabih","Da bi se odvojio od Mekke","Da bi ranije počeo trgovati"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Kako je mladost Muhammeda ﷺ djelovala na ljude prije poslanstva?', '["Plašili su ga se","Gledali su u njemu čovjeka čista karaktera i lijepe naravi","Smatrali su ga lašcem","Nisu ga poznavali"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Kada su Mekkelije imale spor oko Crnog kamena pri obnovi Kabe, zašto su bile spremne prihvatiti rješenje Muhammeda ﷺ?', '["Jer je bio najstariji među njima","Jer je bio kralj","Jer su mu vjerovali zbog njegove mudrosti i poštenja","Jer je imao vojsku"]'::jsonb, 2, NULL, NULL, '', NULL, 'single'),
  ('Šta ta epizoda s Crnim kamenom govori o Muhammedu ﷺ i prije objave?', '["Da je bio običan posmatrač","Da su ljudi u njemu vidjeli pravednog i smirenog čovjeka","Da nije volio rješavati sporove","Da se povlačio od svakog problema"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Kako se zvala čestita i ugledna žena koja je kasnije postala supruga Muhammeda ﷺ i prva mu pružila duboku podršku?', '["Amina","Hatidža","Aiša","Sevda"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Zašto je brak s Hatidžom bio važan period u životu Muhammeda ﷺ?', '["Jer je tada postao vođa Mekke","Jer je dobio kućni mir, dostojanstvo i oslonac u čestitoj supruzi","Jer je napustio trgovinu","Jer je tada prvi put napustio Mekku"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Koja rečenica najbolje opisuje Muhammeda ﷺ prije objave?', '["Bio je poznat po snazi i borbama","Bio je poznat po istini, stidu, poštenju i lijepom karakteru","Bio je poznat po bogatstvu i raskoši","Bio je poznat po pjesništvu"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Šta je Muhammed ﷺ već u mladosti pokazivao svojim ponašanjem, iako tada još nije bio objavljen kao poslanik?', '["Da voli vlast","Da je njegovo srce vezano za istinu i čestitost","Da želi biti poznat","Da izbjegava odgovornost"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Zašto je djetinjstvo Muhammeda ﷺ važna priprema za kasniju misiju?', '["Jer ga je Allah kroz iskušenja učio blagosti, saburu i razumijevanju ljudi","Jer je tada naučio vladati vojskom","an\", "]'::jsonb, 0, NULL, NULL, '', NULL, 'single'),
  ('Koja osobina posebno povezuje rani život Poslanika ﷺ s njegovom kasnijom poslaničkom misijom?', '["Ljubav prema svađi","Dosljedna iskrenost","Želja za slavom","Povlačenje od svakog čovjeka"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('Koja je glavna pouka ovog prvog perioda života Muhammeda ﷺ?', '["Veliki ljudi nastaju samo iz bogatih kuća","Allah odgaja Svoga roba kroz iskušenja, poštenje i lijep karakter","Dovoljno je biti voljen među ljudima","Najvažnije je imati mnogo prijatelja"]'::jsonb, 1, NULL, NULL, '', NULL, 'single'),
  ('IZBACI ULJEZA: Koja riječ ne pripada nizu? Šehadet, Namaz, Iman, Post', '["Šehadet","Namaz","Iman","Post"]'::jsonb, 2, NULL, NULL, 'Iman (vjerovanje) nije islamski šart. Šehadet, namaz i post su islamski šarti.', NULL, 'single'),
  ('IZBACI ULJEZA: Allah, Meleki, Džamija, Knjige', '["Allah","Meleki","Džamija","Knjige"]'::jsonb, 2, NULL, NULL, 'Allah, meleki i knjige su dio imanskih šarta, a džamija nije.', NULL, 'single'),
  ('Riječ BISMILLA vas asocira na:', '["Završetak posla","Početak svakog posla","Zahvalu","Oprost"]'::jsonb, 1, NULL, NULL, 'Bismilla (U ime Allaha) se uči na početku svakog posla.', NULL, 'single'),
  ('Broj 6 vas asocira na:', '["Islamske šarte","Imanske šarte","Namaske šarte","Abdeske šarte"]'::jsonb, 1, NULL, NULL, 'Imanskih šarta ima šest: vjerovanje u Allaha, meleke, knjige, poslanike, Sudnji dan i kader.', NULL, 'single'),
