  ('Poredaj 5 islamskih šartova:', '["Šehadet","Namaz","Post","Zekat","Hadž"]'::jsonb, 0, NULL, '[1,2,3,4,5]'::jsonb, 'Pet islamskih šartova (stubova islama).', NULL, 'reorder'),
  ('Poredaj 4 abdeska šarta:', '["Umiti lice","Oprati ruke do lakata","Namazati glavu","Oprati noge do članaka"]'::jsonb, 0, NULL, '[1,2,3,4]'::jsonb, 'Četiri abdeska farza.', NULL, 'reorder'),
  ('Poredaj 6 namaskih ruknova:', '["Iftitahi-tekbir","Kijam","Kiraet","Ruku''","Sedžda","Kadei-ehire"]'::jsonb, 0, NULL, '[1,2,3,4,5,6]'::jsonb, 'Šest namaskih ruknova.', NULL, 'reorder'),
  ('Poredaj 5 dnevnih namaza:', '["Sabah","Podne","Ikindija","Akšam","Jacija"]'::jsonb, 0, NULL, '[1,2,3,4,5]'::jsonb, 'Pet dnevnih namaza po redu.', NULL, 'reorder'),
  ('Poredaj 4 mubarek-dana:', '["Nova hidžretska godina","Mevlud","Ramazanski bajram","Kurban-bajram"]'::jsonb, 0, NULL, '[1,2,3,4]'::jsonb, 'Četiri glavna mubarek-dana.', NULL, 'reorder'),
  ('Poredaj Kelime-i šehadet:', '["Ešhedu en la ilahe","illallah","ve ešhedu enne Muhammeden","''abduhu ve resuluhu"]'::jsonb, 0, NULL, '[1,2,3,4]'::jsonb, 'Kelime-i šehadet po redu.', NULL, 'reorder'),
  ('Poredaj prvih 6 hidžretskih mjeseci:', '["Muharrem","Safer","Rebiul-evvel","Rebiul-ahir","Džumadel-ula","Džumadel-uhra"]'::jsonb, 0, NULL, '[1,2,3,4,5,6]'::jsonb, 'Prvih 6 mjeseci hidžretske godine.', NULL, 'reorder'),
  ('Poredaj kadei-ehire:', '["Et-Tehijatu","Salavati","Dove"]'::jsonb, 0, NULL, '[1,2,3]'::jsonb, 'Posljednje sjedenje u namazu.', NULL, 'reorder'),
  ('Poredaj jedan rekat:', '["Kijam + Kiraet","Ruku''","Sedžda","Sedžda (druga)"]'::jsonb, 0, NULL, '[1,2,3,4]'::jsonb, 'Jedan rekat po redu.', NULL, 'reorder'),
  ('Namaskih šarta ima ukupno dvanaest.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Namaskih šarta ima 12: 6 uvjeta (priprema za namaz) i 6 ruknova (sastavni dijelovi namaza).', NULL, 'single'),
  ('Abdest je vjersko pranje cijelog tijela.', '["DA","NE"]'::jsonb, 1, NULL, NULL, 'Abdest je vjersko pranje određenih dijelova tijela (lice, ruke, glava, noge). Pranje cijelog tijela je gusul.', NULL, 'single'),
  ('Abdeskih šarta (farzova) ima četiri.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Četiri abdeska šarta su: oprati lice, oprati ruke do iznad lakata, potrati glavu (mesh) i oprati noge do iznad članaka.', '/assets/images/pitanja/abdest.jpg', 'single'),
  ('Spavanje kvari abdest.', '["NE","DA"]'::jsonb, 1, NULL, NULL, 'Abdest kvari: spavanje ili gubitak svijesti, oticanje krvi, povraćanje, prirodna nužda i glasno smijanje u namazu.', '/assets/images/pitanja/spavanje.jpg', 'single'),
  ('Sura En-Nas je prva sura u Kur''anu.', '["NE","DA"]'::jsonb, 0, NULL, NULL, 'Sura En-Nas je posljednja (114.) sura u Kur''anu. Prva sura je El-Fatiha.', '/assets/images/pitanja/nas.jpg', 'single'),
  ('Gusulskih šarta ima tri.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tri gusulska šarta su: gargara (ispiranje usta), istinšak (ispiranje nosa) i pranje cijelog tijela.', NULL, 'single'),
  ('Tejemum se obavlja kada nemamo vode za abdest.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tejemum je simboličko čišćenje zemljom kada nemamo vode ili ne možemo koristiti vodu.', NULL, 'single'),
  ('U džamiju ulazimo lijevom nogom.', '["NE","DA"]'::jsonb, 0, NULL, NULL, 'U džamiju, kuću, školu i mekteb ulazimo DESNOM nogom, a izlazimo lijevom.', '/assets/images/pitanja/desna_noga.jpg', 'single'),
  ('Kijam je stajanje u namazu.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Kijam je drugi namaski rukn - stajanje u namazu kada učimo Subhaneke, Fatihu i suru.', '/assets/images/pitanja/namaz_dzemat.jpg', 'single'),
  ('Ruku'' je spuštanje lica na tlo.', '["NE","DA"]'::jsonb, 0, NULL, NULL, 'Ruku'' je pregibanje u namazu (savijanje do polovine tijela). Spuštanje lica na tlo je sedžda.', '/assets/images/pitanja/sedzda.jpg', 'single'),
  ('Sure El-Felek i En-Nas se nazivaju ''Zaštitnice''.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'El-Felek i En-Nas su ''zaštitnice'' (mu''avvizetejn) - sure kojima tražimo zaštitu od zla.', NULL, 'single'),
  ('Kadei-ehire je sjedenje na kraju namaza.', '["NE","DA"]'::jsonb, 1, NULL, NULL, 'Kadei-ehire je posljednje sjedenje u namazu na kojem učimo Et-Tehijatu, salavate i dove.', '/assets/images/pitanja/sjedenje_z.jpg', 'single'),
  ('Namaz se može klanjati kada Sunce izlazi.', '["DA","NE"]'::jsonb, 1, NULL, NULL, 'Namaz se ne može klanjati: kada Sunce izlazi, kada je na sredini neba i kada zalazi.', NULL, 'single'),
  ('Mesh je potiranje mokrom rukom po glavi.', '["NE","DA"]'::jsonb, 1, NULL, NULL, 'Mesh je treći abdeski šart - potiranje najmanje četvrtine glave mokrom rukom.', '/assets/images/pitanja/mesh.jpg', 'single'),
  ('Tejemumskih šarta ima tri.', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Tri tejemumska šarta: nijet, potiranje lica zemljom i potiranje ruku do iznad lakata zemljom.', '/assets/images/pitanja/tejemmum.jpg', 'single'),
  ('Šta ne pripada ovdje?', '["Tijesna","Plava","Kratka","Providna"]'::jsonb, 1, NULL, NULL, 'Odjeća tokom obavljajna namaza ne smije biti tijesna, kratka i providna. Može biti raznih boja.', NULL, 'single'),
  ('Koji je prvi namaski šart (uvjet)?', '["Abdest","Kibla","Čistoća tijela odjeće i mjesta","Nijet"]'::jsonb, 2, NULL, NULL, 'Prvi namaski uvjet je čistoća tijela, odjeće i mjesta za klanjanje.', NULL, 'single'),
  ('Koliko se puta kaže Allahu ekber tokom učenja ezana?', '["4","5","2","6"]'::jsonb, 3, NULL, NULL, '6 puta', NULL, 'single'),
  ('Šta je kibla?', '["Namaski rukn","Vrsta abdesta","Vrsta namaza","Smjer prema Kabi u Mekki"]'::jsonb, 3, NULL, NULL, 'Kibla je smjer prema Kabi u Mekki. Muslimani se okreću prema kibli kada klanjaju namaz.', '/assets/images/pitanja/kaba.jpg', 'single'),
  ('Šta učimo na ruku''u?', '["Semiallahu limen hamideh","Subhane Rabbijel-e''ala","Subhane Rabbijel-''azim","Et-Tehijatu"]'::jsonb, 2, NULL, NULL, 'Na ruku''u tri puta učimo ''Subhane Rabbijel-''azim'' - Slavljen je moj Gospodar Veličanstveni.', '/assets/images/pitanja/ruku_boy.jpg', 'single'),
  ('Šta učimo na sedždi?', '["Allahu ekber","Subhane Rabbijel-e''ala","Subhane Rabbijel-''azim","Rabbena lekel-hamd"]'::jsonb, 1, NULL, NULL, 'Na sedždi tri puta učimo ''Subhane Rabbijel-e''ala'' - Slavljen je moj Gospodar Uzvišeni.', '/assets/images/pitanja/sedzda.jpg', 'single'),
  ('Koja sura je posljednja u Kur''anu?', '["El-Felek","El-Ihlas","En-Nas","El-Kevser"]'::jsonb, 2, NULL, NULL, 'Sura En-Nas je 114. i posljednja sura u Kur''anu. Govori o traženju zaštite od šejtana.', NULL, 'single'),
  ('Šta je iftitahi-tekbir?', '["Završetak namaza","Pregibanje","Početni tekbir","Sjedenje u namazu"]'::jsonb, 2, NULL, NULL, 'Iftitahi-tekbir je početni tekbir (Allahu ekber) kojim započinjemo namaz nakon nijeta.', '/assets/images/pitanja/iftitahi_tekbir.jpg', 'single'),
  ('Namaz sa najmanje rekata je sabah. Koliko ima rekata?', '["Dva","Tri","Četiri","Pet"]'::jsonb, 2, NULL, NULL, 'Sabah-namaz ima 4 rekata: 2 rekata sunneta i 2 rekata farza.', NULL, 'single'),
  ('Čime se obavlja tejemum?', '["Vodom","Zemljom","Pijeskom","Kamenjem"]'::jsonb, 1, NULL, NULL, 'Tejemum se obavlja čistom suhom zemljom ili predmetom od zemlje (kamen, zid).', NULL, 'single'),
  ('Šta je kiraet?', '["Učenje Kur''ana u namazu","Sjedenje","Stajanje u namazu","Pregibanje"]'::jsonb, 0, NULL, NULL, 'Kiraet je treći namaski rukn - učenje Kur''ana (Fatihe i sure) stojeći u namazu.', '/assets/images/pitanja/kiraet2.jpg', 'single'),
  ('Kojom nogom izlazimo iz džamije?', '["Desnom","Lijevom","Obje istovremeno","Svejedno"]'::jsonb, 1, NULL, NULL, 'Iz džamije, kuće i škole izlazimo lijevom nogom, a ulazimo desnom.', NULL, 'single'),
  ('Ko uči ezan?', '["Imam","Mujezin","Hatib","Muallim"]'::jsonb, 1, NULL, NULL, 'Mujezin je osoba koja uči ezan - poziv na namaz sa munare džamije.', NULL, 'single'),
  ('Šta nije dio jednog rekata?', '["Kijam","Kiraet","Ruku''","Dvije sedžde","Kadei ehire"]'::jsonb, 4, NULL, NULL, 'Jedan rekat čine: kijam (stajanje) + kiraet (učenje) + ruku'' + dvije sedžde.', NULL, 'single'),
  ('Šta NE kvari abdest?', '["Spavanje","Plakanje","Povraćanje","Krvarenje"]'::jsonb, 1, NULL, NULL, 'Plakanje NE kvari abdest. Abdest kvare: spavanje, povraćanje, krvarenje i prirodna nužda.', NULL, 'single'),
  ('Šta ne spada u namaske ruknove?', '["Kijam","Ruku''","Abdest","Sedžda"]'::jsonb, 2, NULL, NULL, 'Abdest je namaski UVJET (priprema za namaz), a ne rukn. Kijam, ruku'' i sedžda su ruknovi.', NULL, 'single'),
  ('Koja riječ ne pripada ovdje?', '["Kijam","Kibla","Iftitahi-tekbir","Sedžda"]'::jsonb, 1, NULL, NULL, 'Kibla je namaski uvjet (smjer), dok su iftitahi-tekbir, kijam i sedžda namaski ruknovi.', NULL, 'single'),
  ('Šta nije farz abdesta?', '["Pranje lica","Mesh glave","Gargara","Pranje nogu"]'::jsonb, 2, NULL, NULL, 'Gargara (ispiranje usta i grla) je farz GUSULA, ne abdesta. Četiri abdeska šarta su: lice, ruke, mesh i noge.', NULL, 'single'),
  ('Šta od ovoga nije sura?', '["Ihlas","Nas","Subhaneke","Felek"]'::jsonb, 2, NULL, NULL, 'Subhaneke nije sura nego dova u kojoj slavimo Allaha na početku namaza', '/assets/images/pitanja/razmislja.jpg', 'single'),
  ('Kad kametis-salah se uči u...', '["Ezanu","Ikametu","Ajetul-kursiji","Prije uzimanja abdesta"]'::jsonb, 1, NULL, NULL, 'Namaskih šarta ima 12: 6 uvjeta prije namaza i 6 ruknova u toku namaza.', NULL, 'single'),
  ('Riječ ''Kaba'' vas asocira na:', '["Medinu","Minaret","Kiblu","Mihrab"]'::jsonb, 2, NULL, NULL, 'Kaba je građevina u Mekki prema kojoj se muslimani okreću (kibla) prilikom klanjanja namaza.', '/assets/images/pitanja/kaba1.jpg', 'single'),
  ('Riječ ''mesh'' vas asocira na:', '["Pranje lica","Potiranje glave","Pranje nogu","Gargaru"]'::jsonb, 1, NULL, NULL, 'Mesh je potiranje mokrom rukom najmanje četvrtine glave - treći abdeski šart.', NULL, 'single'),
  ('Izraz ''Subhane Rabbijel-e''ala'' vas asocira na:', '["Ruku''","Sedždu","Kijam","Sjedenje"]'::jsonb, 1, NULL, NULL, '''Subhane Rabbijel-e''ala'' (Slavljen je Gospodar moj Uzvišeni) učimo na sedždi tri puta.', NULL, 'single'),
  ('Riječ ''džunub'' vas asocira na:', '["Abdest","Gusul","Tejemum","Namaz"]'::jsonb, 1, NULL, NULL, 'Džunub je stanje nečistoće koje zahtijeva gusul (obavezno kupanje).', NULL, 'single'),
  ('Odgonetni riječ koja fali. Abdest : voda = Tejemum : ?', '["Pijesak","Voda","Zemlja","Zrak"]'::jsonb, 2, NULL, NULL, 'Kao što se abdest uzima vodom, tako se tejemum obavlja zemljom (ili predmetom od zemlje).', NULL, 'single'),
  ('Odgonetni riječ koja fali. Kijam : stajanje = Ruku'' : ?', '["Sjedenje","Pregibanje","Ležanje","Hodanje"]'::jsonb, 1, NULL, NULL, 'Kijam je stajanje u namazu, a ruku'' je pregibanje (savijanje do polovine tijela).', NULL, 'single'),
  ('Odgonetni riječ koja fali. Iftitahi-tekbir : početak = Selam : ?', '["Kraj","Sredina","Pauza","Početak"]'::jsonb, 0, NULL, NULL, 'Iftitahi-tekbir je početak namaza, a selam (Es-selamu alejkum) je kraj namaza.', '/assets/images/pitanja/iftitahi_tekbir.jpg', 'single'),
  ('Može lise kanjati na stadionu, na travi?', '["DA","NE"]'::jsonb, 0, NULL, NULL, 'Namaz se može klanjati na svakom čistom mjestu: na travi, na asvaltu, na zemlji, na betonu,...', '/assets/images/pitanja/namaz_dzemat.jpg', 'single'),
  ('Odgonetni riječ koja fali. Sabah : jutro = Akšam : ?', '["Veče","Popodne","Noć","Podne"]'::jsonb, 0, NULL, NULL, 'Sabah je jutarnji namaz, a akšam je večernji namaz (klanja se nakon zalaska Sunca).', '/assets/images/pitanja/aksam_grad.jpg', 'single'),
  ('KO SAM JA? Ja sam namaski rukn. Na meni učite ''Subhane Rabbijel-''azim''.', '["Ruku''","Kadei-ehire","Kijam","Sedžda"]'::jsonb, 0, NULL, NULL, 'Ruku'' je pregibanje u namazu - savijanje do polovine tijela uz učenje ''Subhane Rabbijel-''azim''.', '/assets/images/pitanja/ruku_boy.jpg', 'single'),
  ('KO SAM JA? Ja sam namaski rukn. Spuštate lice na tlo. Na meni učite ''Subhane Rabbijel-e''ala''.', '["Kijam","Kiraet","Ruku''","Sedžda"]'::jsonb, 3, NULL, NULL, 'Sedžda je spuštanje lica (čela i nosa) na tlo uz učenje ''Subhane Rabbijel-e''ala''.', '/assets/images/pitanja/sedzda_boy.jpg', 'single'),
  ('ŠTA SAM JA? Ja sam simboličko čišćenje. Koristim se kada nema vode. Obavljam se zemljom.', '["Istindža","Abdest","Gusul","Tejemum"]'::jsonb, 3, NULL, NULL, 'Tejemum je simboličko čišćenje zemljom kada nema vode ili se voda ne može koristiti.', '/assets/images/pitanja/tejemmum.jpg', 'single'),
  ('KO SAM JA? Ja sam posljednja sura u Kur''anu. Tražim zaštitu od šejtana. Zovem se ''Ljudi''.', '["En-Nas","El-Ihlas","El-Felek","El-Kevser"]'::jsonb, 0, NULL, NULL, 'Sura En-Nas (Ljudi) je 114. i posljednja sura Kur''ana - tražimo zaštitu od šejtana.', '/assets/images/pitanja/razmislja.jpg', 'single'),
  ('ŠTA SAM JA? Ja sam poziv na namaz. Učim se sa munare. Uči me mujezin.', '["Ezan","Dova","Hutba","Ikamet"]'::jsonb, 0, NULL, NULL, 'Ezan je poziv na namaz koji mujezin uči sa munare kako bi obavijestio muslimane o namaskom vremenu.', '/assets/images/pitanja/ezan.jpg', 'single'),
  ('DOPUNI NIZ: Iftitahi-tekbir, kijam, kiraet, ruku'', sedžda, ...?', '["Selam","Kadei-ehire","Ezan","Nijet"]'::jsonb, 1, NULL, NULL, 'Šest namaskih ruknova su: 1) iftitahi-tekbir, 2) kijam, 3) kiraet, 4) ruku'', 5) sedžda, 6) kadei-ehire.', NULL, 'single'),
  ('DOPUNI NIZ: Čistoća, abdest, odjeća, vrijeme, kibla, ...?', '["Ruku''","Nijet","Sedžda","Kijam"]'::jsonb, 1, NULL, NULL, 'Šest namaskih uvjeta: 1) čistoća, 2) abdest, 3) odjeća, 4) vrijeme, 5) Kibla, 6) nijet.', NULL, 'single'),
  ('Kada se uči ikamet?', '["Prije spavanja","Poslije namaza","Prije sunneta","Prije farza"]'::jsonb, 3, NULL, NULL, 'Ikamet uče muškarci prije svakog farz namaza', NULL, 'single'),
  ('DOPUNI NIZ: Umiti lice, oprati ruke, mesh glave, ...?', '["Gargara","Oprati noge","Istinšak","Potrati vrat"]'::jsonb, 1, NULL, NULL, 'Četiri abdeska šarta: 1) oprati lice, 2) oprati ruke do lakata, 3) mesh glave, 4) oprati noge.', NULL, 'single'),
  ('DOPUNI NIZ: Gargara, istinšak, ...?', '["Mesh","Gasli vudžud","Abdest","Nijet"]'::jsonb, 1, NULL, NULL, 'Tri gusulska šarta: 1) gargara (ispiranje usta), 2) istinšak (ispiranje nosa), 3) gasli vudžud (pranje tijela).', NULL, 'single'),
  ('SITUACIJA: Ahmed mora klanjati namaz, ali nema vode u blizini. Šta treba uraditi?', '["Ne klanjati","Uzeti tejemum","Čekati vodu","Klanjati bez čistoće"]'::jsonb, 1, NULL, NULL, 'Kada nema vode, uzima se tejemum (simboličko čišćenje zemljom) i klanja namaz.', NULL, 'single'),
  ('SITUACIJA: Merjem je zaboravila na koju stranu treba predati selam prvo. Koja je ispravna?', '["Samo desna","Lijeva pa desna","Desna pa lijeva","Samo lijeva"]'::jsonb, 2, NULL, NULL, 'Selam se prvo predaje na DESNU stranu, pa zatim na lijevu stranu.', '/assets/images/pitanja/selam_desno.jpg', 'single'),
  ('SITUACIJA: Hasan ulazi u džamiju. Kojom nogom treba ući?', '["Lijevom","Desnom","Svejedno","Obje istovremeno"]'::jsonb, 1, NULL, NULL, 'U džamiju, kuću, školu i mekteb ulazimo DESNOM nogom, a izlazimo lijevom.', '/assets/images/pitanja/desna_noga.jpg', 'single'),
  ('SITUACIJA: Selma se glasno nasmijala tokom namaza. Šta se desilo s njenim abdestom?', '["Pokvario se","Obnovio se","Ništa","Pojačao se"]'::jsonb, 0, NULL, NULL, 'Glasno smijanje u namazu kvari i namaz i abdest. Potrebno je ponovo uzeti abdest i klanjati namaz.', '/assets/images/pitanja/djevojcica_namaz.jpg', 'single'),
  ('PRONAĐI GREŠKU: Namaski ruknovi su: Kijam, Kibla, Ruku'', Sedžda, Kadei-ehire, Iftitahi-tekbir.', '["Kijam","Ruku''","Sedžda","Kibla"]'::jsonb, 3, NULL, NULL, 'KIBLA je namaski UVJET, a ne rukn! Šesti rukn je kiraet (umjesto kible).', NULL, 'single'),
  ('Koliko mjeseci ima hidžretska godina?', '["10","11","12","13"]'::jsonb, 2, NULL, NULL, 'Hidžretska godina ima 12 mjeseci.', NULL, 'single'),
  ('Kada se obilježava Ramazanski bajram?', '["Poslije mjeseca ramazana","Prvi ševvala","Poslije posta","Poslije hadža"]'::jsonb, 0, '[0,1,2]'::jsonb, NULL, 'Ramazanski bajram je prvi dan mjeseca ševvala, poslije mjeseca ramazana i posta.', NULL, 'multiple'),
  ('Kada se obilježava Kurban-bajram?', '["Deseti zul-hidžea","Poslije hadža","Poslije posta","Traje 4 dana"]'::jsonb, 0, '[0,1,3]'::jsonb, NULL, 'Kurban-bajram počinje 10. zul-hidžea, poslije hadža, i traje 4 dana.', NULL, 'multiple'),
  ('Šta učimo na Kurban-bajram?', '["Tekbirje","Allahu ekber","Fatihu","Salavate"]'::jsonb, 0, '[0,1]'::jsonb, NULL, 'Na Kurban-bajram učimo tekbirje koji počinju sa "Allahu ekber...".', NULL, 'multiple'),
  ('Prvi dan hidžretskog kalendara je:', '["Petak","Subota","Nedjelja","Ponedjeljak"]'::jsonb, 0, NULL, NULL, 'Prvi dan sedmice hidžretskog kalendara je petak.', NULL, 'single'),
  ('Koliko dana traje hidžretska godina?', '["355 dana","365 dana","354 dana","366 dana"]'::jsonb, 0, NULL, NULL, 'Hidžretska (lunarna) godina ima 355 dana.', NULL, 'single'),
  ('Šta radimo na Ramazanski bajram?', '["Klanjamo bajram-namaz","Idemo na mezarje","Učimo Fatihu","Posjećujemo rodbinu"]'::jsonb, 0, '[0,1,2,3]'::jsonb, NULL, 'Na Ramazanski bajram klanjamo bajram-namaz, idemo na mezarje, učimo Fatihu i posjećujemo rodbinu.', NULL, 'multiple'),
  ('Odaberi ispravno značenje izraza?', '["Rabbi jessir - Gospodaru olakšaj","Rabbi zidni ilma - Gospodaru pomozi mi","Allahu rabbi - Allah je moj Gospodar","Hasbi rabbi - moj učitelj"]'::jsonb, 0, '[0,2]'::jsonb, NULL, 'Rabbi jessir = olakšaj, Rabbi zidni ilma = proširi znanje, Allahu rabbi = Allah moj Gospodar.', NULL, 'multiple'),
  ('Poredaj dovu Rabbi jessir:', '["Rabbi jessir","ve la tu''assir","Rabbi temmim","bil-hajr!"]'::jsonb, 0, NULL, '[1,2,3,4]'::jsonb, 'Rabbi jessir: Gospodaru olakšaj, a ne otežaj, dovrši sa dobrom!', NULL, 'reorder'),
  ('Poredaj riječi dove za povećanje znanja:', '["Rabbi","zidni","''ilma"]'::jsonb, 0, NULL, '[1,2,3]'::jsonb, 'Rabbi zidni ''ilma: Gospodaru moj, znanje moje proširi!', NULL, 'reorder'),
  ('Poredaj prvih 6 mjeseci hidžretske godine:', '["Muharrem","Safer","Rebiul-evvel","Rebiul-ahir","Džumadel-ula","Džumadel-uhra"]'::jsonb, 0, NULL, '[1,2,3,4,5,6]'::jsonb, 'Prvih 6 mjeseci hidžretske godine.', NULL, 'reorder'),
  ('Poredaj drugih 6 mjeseci hidžretske godine:', '["Redžeb","Ša''ban","Ramazan","Ševval","Zul-kade","Zul-hidže"]'::jsonb, 0, NULL, '[1,2,3,4,5,6]'::jsonb, 'Drugih 6 mjeseci hidžretske godine.', NULL, 'reorder'),
